// ═══════════════════════════════════════════
//  PIXEL PARTIES — GAME BOARD
//  BoardCard, BoardZone, animations, effects,
//  prompts, and the main GameBoard component
// ═══════════════════════════════════════════
const { useState, useEffect, useRef, useCallback, useMemo, useContext, useLayoutEffect } = React;
const { api, emitSocket, socket, AppContext, CardMini, FoilOverlay, useFoilBands,
        cardImageUrl, skinImageUrl, typeColor, typeClass, CARDS_BY_NAME, SKINS_DB } = window;

// ═══════════════════════════════════════════
//  TYPEWRITER TEXT (win/loss speech bubbles)
//  Reveals a message letter-by-letter (fast) and renders lightweight
//  markup: *italic* and **bold**. Used for both players' end-game lines.
// ═══════════════════════════════════════════
// Split a string into formatted runs. `**` toggles bold, a lone `*` toggles
// italic; the markers themselves are consumed, not shown.
function parseBubbleMarkup(str) {
  const segs = [];
  let bold = false, italic = false, buf = '';
  const flush = () => { if (buf) { segs.push({ text: buf, bold, italic }); buf = ''; } };
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '*' && str[i + 1] === '*') { flush(); bold = !bold; i++; continue; }
    if (str[i] === '*') { flush(); italic = !italic; continue; }
    buf += str[i];
  }
  flush();
  return segs;
}

// Per-character "is this letter part of a SHOUTED (all-caps) word?" flags.
// A word = a maximal letter-run; it shouts if it's 2+ letters and entirely
// uppercase (so "BOOM"/"HA" bob, but a lone "I"/"A" or "Ha" don't). Shouted
// letters get a slight up/down wobble (.cpu-shout-letter) to read as yelling.
function shoutFlags(text) {
  const flags = new Array(text.length).fill(false);
  const re = /[A-Za-z]+/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const w = m[0];
    if (w.length >= 2 && w === w.toUpperCase()) {
      for (let i = 0; i < w.length; i++) flags[m.index + i] = true;
    }
  }
  return flags;
}

function TypewriterText({ text, speed = 26 }) {
  const segs = useMemo(() => parseBubbleMarkup(text || ''), [text]);
  const total = useMemo(() => segs.reduce((n, s) => n + s.text.length, 0), [segs]);
  const [shown, setShown] = useState(0);
  useEffect(() => {
    setShown(0);
    if (!total) return;
    const id = setInterval(() => {
      setShown(prev => {
        if (prev >= total) { clearInterval(id); return prev; }
        return prev + 1;
      });
    }, speed);
    return () => clearInterval(id);
  }, [text, total, speed]);
  // Slice the formatted runs to the number of revealed characters. Within
  // each run, all-caps-word letters become individually-wobbling spans
  // (phase-staggered by absolute position for a trembling "scream" wave);
  // everything else stays plain text.
  let left = shown;
  let offset = 0; // absolute char position across the whole message
  return (
    <>
      {segs.map((s, i) => {
        if (left <= 0) { offset += s.text.length; return null; }
        const piece = s.text.slice(0, left);
        left -= piece.length;
        const flags = shoutFlags(s.text);
        const children = [];
        let buf = '';
        // ALL-CAPS-Fix: die Wobble-Buchstaben sind einzelne
        // inline-block-Spans — für den Zeilenumbruch ist damit JEDER
        // Buchstabe eine eigene Umbruch-Einheit, Caps-Wörter brachen
        // mitten im Wort. Zusammenhängende Shout-Buchstaben werden
        // deshalb in einen whiteSpace:nowrap-Wrapper gruppiert, dann
        // wandert das Wort wie normale Wörter komplett in die nächste
        // Zeile (shoutFlags markiert nur [A-Za-z]-Runs, Leerzeichen
        // trennen die Gruppen also von selbst).
        let word = null;
        const flushWord = (idx) => {
          if (word) {
            children.push(<span key={'w' + idx} style={{ whiteSpace: 'nowrap' }}>{word}</span>);
            word = null;
          }
        };
        for (let c = 0; c < piece.length; c++) {
          if (flags[c]) {
            if (buf) { children.push(buf); buf = ''; }
            (word = word || []).push(
              <span key={'s' + c} className="cpu-shout-letter" style={{ animationDelay: ((offset + c) * -0.07) + 's' }}>{piece[c]}</span>
            );
          } else {
            flushWord(c);
            buf += piece[c];
          }
        }
        flushWord(piece.length);
        if (buf) children.push(buf);
        offset += s.text.length;
        return (
          <span key={i} style={{ fontWeight: s.bold ? 800 : undefined, fontStyle: s.italic ? 'italic' : undefined }}>{children}</span>
        );
      })}
    </>
  );
}

// ═══════════════════════════════════════════
//  SHARED BOARD TOOLTIP SYSTEM
//  Single tooltip rendered in GameBoard, driven
//  by mouse events from BoardCard / CardRevealEntry.
//  Eliminates orphan portal tooltips.
// ═══════════════════════════════════════════
let _activeLuckTooltipTarget = null;
let _boardTooltipLocked = false;
// While a card is being dragged, suppress all card-hover tooltips — the
// preview gets in the way of seeing the drop target. Flipped from the
// drag-state effect below and consulted on every setBoardTooltip(...)
// call, so any hover that tries to open a preview mid-drag is ignored.
let _isDraggingCard = false;
function setBoardTooltip(card) {
  // When locked (prompt card hovered), ignore external clears
  if (!card && _boardTooltipLocked) return;
  if (card && _isDraggingCard) return;
  window._boardTooltipSetter?.(card);
}

// ── Rusting Crystal / BGG cost helpers ───────────────────────
// Mirror of `applyRustingCrystalCostMultiplier` in server.js so the
// hand-card cost UI matches what the server actually charges. While
// a copy of "Rusting Crystal" sits in `me`'s hand, the base cost of
// every OTHER Artifact is doubled — unless "Big Gwen Guard" is in
// one of `me`'s Support Zones (its passive aura suppresses all self-
// reveal Crystal effects). Idempotent / non-stacking: multiple
// Rusting Crystals still produce a single ×2.
function _meControlsBigGwenGuard(me) {
  if (!me?.supportZones) return false;
  for (const heroZones of me.supportZones) {
    if (!Array.isArray(heroZones)) continue;
    for (const slot of heroZones) {
      if (Array.isArray(slot) && slot.includes('Big Gwen Guard')) return true;
    }
  }
  return false;
}

function applyCrystalCostMods(me, cardName, baseCost) {
  if (!me || cardName === 'Rusting Crystal') return baseCost;
  if (!(me.hand || []).includes('Rusting Crystal')) return baseCost;
  if (_meControlsBigGwenGuard(me)) return baseCost;
  return baseCost * 2;
}

function BoardCard({ cardName, faceDown, flipped, label, hp, maxHp, atk, hpPosition, style, noTooltip, skins, tooltipCardOverride, inheritedEffects, revealTooltipWhenFaceDown, abilities, effectiveLevel, stampBonus, showLevelBadge }) {
  const card = faceDown ? null : CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name, skins) : null;
  // A caller (e.g. Biomancy Token in the puzzle builder) can override what
  // the hover tooltip renders without changing the card image / name by
  // passing `tooltipCardOverride`. Falls back to the canonical card.
  // When the BoardCard renders with live stats (hero / creature on the
  // battle board), pass them through to the tooltip via `_liveHp` /
  // `_liveMaxHp` / `_liveAtk` so the hover preview shows
  // `currentHp / maxHp` and current ATK instead of the base card-DB
  // values. CardTooltipContent prefers `_live*` over `card.*`.
  // `inheritedEffects` (an array of `{label, text}`) is mirrored from
  // the engine's per-instance `_inheritedEffects` counter for cards that
  // pick up rules text from another card (Sparkfly Queen carrying the
  // gift of a sacrificed Sparkfly via Hive's Crown today; any future
  // card that populates the same counter benefits for free).
  //
  // `revealTooltipWhenFaceDown` is an explicit puzzle-creator opt-in:
  // the card stays visually a cardback but its identity is exposed via
  // the hover tooltip. Live battle never sets this (would leak hidden
  // info). Used today by the Puzzle Creator's opp-side Surprise zones
  // so the author can inspect what they've placed without flipping it.
  const tooltipCardData = (faceDown && revealTooltipWhenFaceDown)
    ? CARDS_BY_NAME[cardName]
    : card;
  const tooltipBase = tooltipCardOverride || tooltipCardData;
  const tooltipTarget = (() => {
    if (!tooltipBase) return null;
    const hasLiveAbilities = Array.isArray(abilities) && abilities.length > 0;
    if (hp == null && maxHp == null && atk == null && effectiveLevel == null && (!inheritedEffects || inheritedEffects.length === 0) && !hasLiveAbilities) return tooltipBase;
    return {
      ...tooltipBase,
      _liveHp:    hp    != null ? hp    : tooltipBase._liveHp,
      _liveMaxHp: maxHp != null ? maxHp : tooltipBase._liveMaxHp,
      _liveAtk:   atk   != null ? atk   : tooltipBase._liveAtk,
      // Lethe pile-stamp aware level — feeds CardTooltipContent's
      // stats line so the hover preview shows the effective Lv (with
      // a "(+N)" suffix when the bonus is non-zero).
      _liveLevel: effectiveLevel != null ? effectiveLevel : tooltipBase._liveLevel,
      _stampBonus: stampBonus != null ? stampBonus : tooltipBase._stampBonus,
      _inheritedEffects: (inheritedEffects && inheritedEffects.length > 0)
        ? inheritedEffects
        : tooltipBase._inheritedEffects,
      // `_liveAbilities` is the per-Hero `abilityZones[heroIdx]`
      // shape — an array of slot arrays, each slot a stack of names
      // (`['Fighting','Fighting']`, `['Toughness']`, `[]`). The
      // tooltip dedupes by base name and renders `Fighting 2`
      // instead of `Fighting, Fighting`. Falls back to the static
      // cards.json `startingAbility1/2` only for off-board card
      // previews where the live stack isn't available.
      _liveAbilities: hasLiveAbilities ? abilities : tooltipBase._liveAbilities,
    };
  })();

  // Foil support
  const foilType = card?.foil || null;
  const isFoil = foilType === 'secret_rare' || foilType === 'diamond_rare';
  const foilClass = foilType === 'diamond_rare' ? 'foil-diamond-rare' : foilType === 'secret_rare' ? 'foil-secret-rare' : '';
  const foilBands = useFoilBands(isFoil);
  const foilMeta = useRef(null);
  if (isFoil && !foilMeta.current) {
    foilMeta.current = {
      shimmerOffset: `${-Math.random() * 5000}ms`,
      sparkleDelays: SPARKLE_POSITIONS.map(sp => sp.delay + Math.random() * 2),
    };
  } else if (!isFoil && foilMeta.current) {
    foilMeta.current = null;
  }

  return (
    <div className={'board-card' + (faceDown ? ' face-down' : '') + (flipped ? ' flipped' : '') + (foilClass ? ' ' + foilClass : '')}
      style={style}
      onMouseEnter={() => !noTooltip && (revealTooltipWhenFaceDown || !faceDown) && tooltipTarget && setBoardTooltip(tooltipTarget)}
      onMouseLeave={() => setBoardTooltip(null)}
      onTouchStart={() => {
        if (noTooltip || (faceDown && !revealTooltipWhenFaceDown) || !tooltipTarget) return;
        window._longPressFired = false;
        window._longPressTimer = setTimeout(() => {
          window._longPressFired = true;
          setTapTooltip(tooltipTarget.name);
          setBoardTooltip(tooltipTarget);
        }, window.LONG_PRESS_MS || 400);
      }}>
      {isFoil && foilMeta.current && <FoilOverlay bands={foilBands} shimmerOffset={foilMeta.current.shimmerOffset} sparkleDelays={foilMeta.current.sparkleDelays} foilType={foilType} />}
      {faceDown ? (
        <img src="/cardback.png" style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
      ) : imgUrl ? (
        <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
      ) : (
        <div className="board-card-text">{cardName || '?'}</div>
      )}
      {label && <div className="board-card-label">{label}</div>}
      {/* Pile-level badge — only shown when the caller opts in via
          `showLevelBadge` (BoardZone for discard / deleted does so).
          Support-zone Creatures suppress this and use the existing
          `.creature-level` badge below the board grid, which already
          accounts for `actionChangeLevel` deltas and Lethe bonuses.
          Purple-tinted + glow when `stampBonus > 0`. */}
      {showLevelBadge && effectiveLevel != null && !faceDown && (
        <div style={{
          position: 'absolute', top: 3, left: 3,
          background: 'rgba(0,0,0,.85)',
          color: stampBonus > 0 ? '#c4a8ff' : '#fff',
          padding: '2px 6px', borderRadius: 4,
          fontSize: 11, fontWeight: 700,
          border: '1px solid ' + (stampBonus > 0 ? '#a288ff' : 'rgba(255,255,255,0.3)'),
          pointerEvents: 'none', zIndex: 4,
          boxShadow: stampBonus > 0 ? '0 0 6px rgba(162,136,255,.6)' : 'none',
        }}>Lv {effectiveLevel}{stampBonus > 0 ? ` (+${stampBonus})` : ''}</div>
      )}
      {hp != null && maxHp != null && hp > maxHp && (
        <div className="board-card-overheal-barrier" />
      )}
      {/* Hero cards: HP + ATK go through the responsive flex strip so
          they auto-stack vertically on cards too narrow to fit both
          numbers on one row. Other positions (creature) keep the
          single-stat absolute layout. */}
      {hpPosition === 'hero' ? (
        (hp != null || atk != null) && (
          <div className="board-card-stats-hero">
            {hp != null && (
              <div className="board-card-hp-num"
                style={maxHp != null && hp > maxHp ? { color: '#44ff88' } : undefined}>
                {hp}
              </div>
            )}
            {atk != null && (
              <div className="board-card-atk-num">{atk}</div>
            )}
          </div>
        )
      ) : (
        hp != null && hpPosition && (
          <div className={'board-card-hp board-card-hp-' + hpPosition}
            style={maxHp != null && hp > maxHp ? { color: '#44ff88' } : undefined}>
            {hp}
          </div>
        )
      )}
    </div>
  );
}

function BoardZone({ type, cards, label, faceDown, flipped, stackLabel, children, onClick, onHoverCard, style, className, dataAttrs, ownerLetheStamps }) {
  const cls = 'board-zone board-zone-' + type + (className ? ' ' + className : '') + ((cards?.length > 0) ? ' zone-has-card' : '');
  const topCardName = cards && cards.length > 0 && !faceDown ? cards[cards.length - 1] : null;
  const suppressChildTooltip = !!onClick && !!onHoverCard;
  // For discard/deleted zones, the top card's effective level is the
  // base printed level plus the max Lethe stamp on any copy of that
  // name in the owner's combined piles. The same value `effectiveCardLevel`
  // uses, so the player sees exactly what the revival gates will see.
  const topLevelInfo = (() => {
    if (!topCardName || (type !== 'discard' && type !== 'deleted')) return null;
    const cd = CARDS_BY_NAME[topCardName];
    if (!cd || cd.cardType !== 'Creature' || cd.level == null) return null;
    const arr = ownerLetheStamps?.[topCardName];
    let stamp = 0;
    if (Array.isArray(arr)) for (const v of arr) if (v > stamp) stamp = v;
    return { effectiveLevel: (cd.level || 0) + stamp, stampBonus: stamp };
  })();
  // BoardZone-level hover dispatch. The shared pile-hover tooltip
  // (rendered at the page root) accepts EITHER a bare card-name string
  // OR an enriched `{ name, effectiveLevel, stampBonus }` object so it
  // can render the Lethe-stamped level without re-reading the player
  // state. Pile/stack hovers without stamp info fall through to the
  // string form — the tooltip handles both shapes.
  const hoverPayload = topCardName == null ? null : (topLevelInfo
    ? { name: topCardName, effectiveLevel: topLevelInfo.effectiveLevel, stampBonus: topLevelInfo.stampBonus }
    : topCardName);
  return (
    <div className={cls + (onClick && cards?.length > 0 ? ' board-zone-clickable' : '')}
      style={style}
      {...(dataAttrs || {})}
      onClick={onClick && cards?.length > 0 ? onClick : undefined}
      onMouseEnter={() => hoverPayload && onHoverCard && !window.activeDragData && !window.deckDragState && onHoverCard(hoverPayload)}
      onMouseLeave={() => onHoverCard && onHoverCard(null)}>
      {cards && cards.length > 0 ? (
        cards.length === 1 ? (
          <BoardCard cardName={cards[0]} faceDown={faceDown} flipped={flipped} label={stackLabel} noTooltip={suppressChildTooltip}
            effectiveLevel={topLevelInfo?.effectiveLevel} stampBonus={topLevelInfo?.stampBonus} showLevelBadge={topLevelInfo != null} />
        ) : (
          <div className="board-stack">
            <BoardCard cardName={cards[cards.length - 1]} faceDown={faceDown} flipped={flipped} label={stackLabel || (cards.length + '')} noTooltip={suppressChildTooltip}
              effectiveLevel={topLevelInfo?.effectiveLevel} stampBonus={topLevelInfo?.stampBonus} showLevelBadge={topLevelInfo != null} />
          </div>
        )
      ) : children || (
        <div className="board-zone-empty">{label || ''}</div>
      )}
    </div>
  );
}

// Briefly tints a board-zone red to signal that the hero/creature in
// that slot just took damage. Restarts the animation if the same slot
// is hit twice in quick succession (e.g. multi-hit attacks).
function flashDamageOnZone(selector) {
  const el = document.querySelector(selector);
  if (!el) return;
  el.classList.remove('damage-flashing');
  // Force reflow so the animation restarts when the class is re-added.
  void el.offsetWidth;
  el.classList.add('damage-flashing');
  setTimeout(() => el.classList.remove('damage-flashing'), 500);
}

// Floating damage number that finds its target hero and animates above it
function DamageNumber({ amount, ownerLabel, heroIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top + r.height * 0.3 });
    }
  }, [ownerLabel, heroIdx]);

  if (!pos) return null;
  // Damage absorbed to 0 → render the bare "0" (no minus sign), so
  // the player sees that the hit was absorbed rather than blocked
  // entirely. Matches the CreatureDamageNumber and HealNumber forms.
  const label = amount > 0 ? `-${amount}` : '0';
  return (
    <div className="damage-number" style={{ left: pos.x, top: pos.y }}>
      {label}
    </div>
  );
}

// Floating heal number for heroes (green, rising)
function HealNumber({ amount, ownerLabel, heroIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top + r.height * 0.3 });
    }
  }, [ownerLabel, heroIdx]);

  if (!pos) return null;
  // Heal-for-0 (full-HP target, or Nao's overheal blocked because the
  // target is already > maxHp) → plain "0", no plus sign. Mirrors the
  // CreatureDamageNumber's "0 damage absorbed" rendering.
  const label = amount > 0 ? `+${amount}` : '0';
  return (
    <div className="damage-number heal-number" style={{ left: pos.x, top: pos.y }}>
      {label}
    </div>
  );
}

// Floating heal number for creatures — same role as CreatureDamageNumber
// but for the heal direction. Used today only for the 0-heal feedback
// broadcast by `play_heal_zero` (Skeleton Healer / Heal targeting a
// full-HP creature, etc.); positive creature heals are not surfaced as
// floating numbers (matching prior behavior — only damage was).
function CreatureHealNumber({ amount, ownerLabel, heroIdx, zoneSlot }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-support-zone="1"][data-support-owner="${ownerLabel}"][data-support-hero="${heroIdx}"][data-support-slot="${zoneSlot}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top + r.height * 0.3 });
    }
  }, [ownerLabel, heroIdx, zoneSlot]);

  if (!pos) return null;
  const label = amount > 0 ? `+${amount}` : '0';
  return (
    <div className="damage-number heal-number" style={{ left: pos.x, top: pos.y }}>
      {label}
    </div>
  );
}

// Floating damage number for creatures (finds by support zone data attributes)
function CreatureDamageNumber({ amount, ownerLabel, heroIdx, zoneSlot }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-support-zone="1"][data-support-owner="${ownerLabel}"][data-support-hero="${heroIdx}"][data-support-slot="${zoneSlot}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top + r.height * 0.3 });
    }
  }, [ownerLabel, heroIdx, zoneSlot]);

  if (!pos) return null;
  // Damage absorbed to 0 → render the bare "0" (no minus sign), so
  // the player sees that the hit was absorbed rather than blocked
  // entirely. Anything > 0 keeps the standard `-N` form.
  const label = amount > 0 ? `-${amount}` : '0';
  return (
    <div className="damage-number" style={{ left: pos.x, top: pos.y }}>
      {label}
    </div>
  );
}

// Floating gold gain number
function GoldGainNumber({ amount, playerIdx, isMe }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-gold-player="${playerIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      // Player's gold: float upward from above. Opponent's gold: float downward from below.
      setPos({ x: r.left - 10, y: isMe ? r.top - 40 : r.bottom + 10, isMe });
    }
  }, [playerIdx]);

  if (!pos) return null;
  return (
    <div className={isMe ? 'gold-gain-number' : 'gold-gain-number gold-gain-down'} style={{ left: pos.x, top: pos.y }}>
      +{amount}
    </div>
  );
}

function GoldLossNumber({ amount, playerIdx, isMe }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const el = document.querySelector(`[data-gold-player="${playerIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left - 10, y: isMe ? r.top - 40 : r.bottom + 10, isMe });
    }
  }, [playerIdx]);

  if (!pos) return null;
  return (
    <div className={isMe ? 'gold-loss-number' : 'gold-loss-number gold-loss-down'} style={{ left: pos.x, top: pos.y }}>
      -{amount}
    </div>
  );
}

// Floating level change number above a creature
function LevelChangeNumber({ delta, owner, heroIdx, zoneSlot, myIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const ownerLabel = owner === myIdx ? 'me' : 'opp';
    const el = document.querySelector(`[data-support-zone][data-support-owner="${ownerLabel}"][data-support-hero="${heroIdx}"][data-support-slot="${zoneSlot}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top });
    }
  }, [owner, heroIdx, zoneSlot]);

  if (!pos) return null;
  return (
    <div className={delta > 0 ? 'level-change-number' : 'level-change-number level-change-negative'} style={{ left: pos.x, top: pos.y }}>
      {delta > 0 ? '+' : ''}{delta}
    </div>
  );
}

// Floating HP change number above a hero (Toughness)
function ToughnessHpNumber({ amount, owner, heroIdx, myIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const ownerLabel = owner === myIdx ? 'me' : 'opp';
    const el = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top - 10 });
    }
  }, [owner, heroIdx]);

  if (!pos) return null;
  return (
    <div className={amount > 0 ? 'toughness-hp-number toughness-hp-up' : 'toughness-hp-number toughness-hp-down'} style={{ left: pos.x, top: pos.y }}>
      {amount > 0 ? '+' : ''}{amount}
    </div>
  );
}

// Floating ATK change number above a hero (Fighting)
function FightingAtkNumber({ amount, owner, heroIdx, myIdx }) {
  const [pos, setPos] = useState(null);
  useEffect(() => {
    const ownerLabel = owner === myIdx ? 'me' : 'opp';
    const el = document.querySelector(`[data-hero-zone][data-hero-owner="${ownerLabel}"][data-hero-idx="${heroIdx}"]`);
    if (el) {
      const r = el.getBoundingClientRect();
      setPos({ x: r.left + r.width / 2, y: r.top - 10 });
    }
  }, [owner, heroIdx]);

  if (!pos) return null;
  return (
    <div className={amount > 0 ? 'fighting-atk-number fighting-atk-up' : 'fighting-atk-number fighting-atk-down'} style={{ left: pos.x, top: pos.y }}>
      {amount > 0 ? '+' : ''}{amount}
    </div>
  );
}

// Floating card that animates from deck position to hand slot position
function DrawAnimCard({ cardName, origIdx, startX, startY, dimmed }) {
  const [endPos, setEndPos] = useState(null);

  useEffect(() => {
    // Wait one frame for the invisible hand slot to be laid out
    requestAnimationFrame(() => {
      const targetSlot = document.querySelector(`.game-hand-me .hand-slot[data-hand-idx="${origIdx}"]`);
      if (targetSlot) {
        const r = targetSlot.getBoundingClientRect();
        setEndPos({ x: r.left, y: r.top });
      }
    });
  }, [origIdx]);

  // Before we know the end position, render at deck position (hidden)
  if (!endPos) return null;

  const dx = endPos.x - startX;
  const dy = endPos.y - startY;

  return (
    <div className={'draw-anim-card' + (dimmed ? ' hand-card-dimmed' : '')}
      style={{ left: startX, top: startY, '--dx': dx + 'px', '--dy': dy + 'px' }}>
      <BoardCard cardName={cardName} />
    </div>
  );
}

// Colored Snow's two-phase Potion reveal. Phase 1 (`exiting === false`)
// runs the in-and-flip keyframes via the base `colored-snow-reveal-card`
// class — the card flies from `startX/Y` to `centerX/Y`, flips face-up,
// and HOLDS at center until the script signals phase 2. Phase 2 toggles
// the `exiting` class on, swapping the animation to the fly-to-
// destination keyframes that target `endX/Y`.
function ColoredSnowRevealCard({ startX, startY, centerX, centerY, endX, endY, exiting, handoff, cardName, cardbackUrl }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const exitClass = handoff ? ' handoff' : (exiting ? ' exiting' : '');
  return (
    <div className={'colored-snow-reveal-card' + exitClass}
      style={{
        '--sx': startX + 'px', '--sy': startY + 'px',
        '--cx': centerX + 'px', '--cy': centerY + 'px',
        '--ex': (endX ?? centerX) + 'px', '--ey': (endY ?? centerY) + 'px',
      }}>
      <div className="colored-snow-reveal-inner">
        <div className="colored-snow-reveal-back">
          <img src={cardbackUrl || '/cardback.png'} draggable={false} />
        </div>
        <div className="colored-snow-reveal-front">
          {imgUrl ? <img src={imgUrl} draggable={false} />
            : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 10, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
        </div>
      </div>
    </div>
  );
}

// Opponent draw animation — face-down card flies from opp deck to opp hand
// Kassaran reveal flip — top card flies from deck pile to screen center,
// flips face-up there, then continues to the destination (hand on match
// or back to deck top on miss). All timing is CSS-driven; this component
// just sets the start / center / end CSS vars and the cardback / face-up
// images. Auto-removed by the scheduler that mounted it after the
// keyframes complete.
function KassaranFlipCard({ startX, startY, centerX, centerY, endX, endY, cardName, cardbackUrl, durationMs }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  return (
    <div className="kassaran-flip-card"
      style={{
        '--sx': startX + 'px', '--sy': startY + 'px',
        '--cx': centerX + 'px', '--cy': centerY + 'px',
        '--ex': endX + 'px', '--ey': endY + 'px',
        // Optional faster reveals (mill_center_reveal) — the CSS
        // animations read `var(--kfDur, 2000ms)`, so existing users
        // (Kassaran, Chaos Magic) keep the 2000ms default untouched.
        ...(durationMs ? { '--kfDur': durationMs + 'ms' } : {}),
      }}>
      <div className="kassaran-flip-inner">
        <div className="kassaran-flip-back">
          <img src={cardbackUrl || '/cardback.png'} draggable={false} />
        </div>
        <div className="kassaran-flip-front">
          {imgUrl ? <img src={imgUrl} draggable={false} />
            : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 10, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
        </div>
      </div>
    </div>
  );
}

// Birthday Present 3-card reveal & pick UI.
//
//   `state` shape:
//     {
//       cards:        [name0, name1, name2],
//       ownerIdx, oppIdx,
//       cardbackUrl:  string (owner's cardback),
//       chosen:       null | string (set when pick lands),
//       flights:      null | [{ cardName, toX, toY }, ...]
//                              (set 200ms after chosen, triggers fly-out),
//     }
//   `interactive` is true on opp's client while the
//   `birthdayPresentPick` prompt is open — enables click-to-pick on each
//   of the three cards. Activator-side renders the same cards with
//   `pointer-events: none` so they just watch.
function BirthdayPresentReveal({ state, interactive, onPick }) {
  const { cards, cardbackUrl, chosen, flights, sourceX, sourceY, castMode } = state;
  return (
    <>
      {cards.map((cardName, i) => {
        const card = CARDS_BY_NAME[cardName];
        const imgUrl = card ? cardImageUrl(card.name) : null;
        const isChosen = chosen === cardName;
        const flight = flights ? flights.find(f => f.cardName === cardName) : null;
        // -1 / 0 / +1 horizontal offset around viewport centre.
        const slotIdx = i - 1;
        const cls = ['bday-present-reveal-card'];
        if (interactive && !chosen) cls.push('clickable');
        // Timeless King Zi: the chosen Spell grows + slow-fades as it's
        // cast (`tk-casting`) instead of Birthday Present's hand-bound
        // highlight (`chosen`). `castMode` is Zi-only — Birthday Present
        // never sets it, so its path is unchanged.
        if (isChosen) cls.push(castMode ? 'tk-casting' : 'chosen');
        if (flight) cls.push('flying-out');
        const handleClick = (interactive && !chosen && onPick)
          ? () => onPick(cardName) : undefined;
        return (
          <div key={`bday-${i}-${cardName}`} className={cls.join(' ')}
            style={{
              '--idx': slotIdx,
              '--delay': (i * 250) + 'ms',
              // Slide-in origin = the activator's deck pile. Captured
              // at event time in the socket handler and threaded
              // through so each card slides FROM that point INTO the
              // centre.
              '--sx': (sourceX != null ? sourceX : 0) + 'px',
              '--sy': (sourceY != null ? sourceY : 0) + 'px',
              ...(flight ? {
                '--ex': flight.toX + 'px',
                '--ey': flight.toY + 'px',
                // Per-flight stagger so user-bound cards land sequentially.
                '--flight-delay': (flight.delay || 0) + 'ms',
              } : {}),
            }}
            onClick={handleClick}>
            <div className="bday-present-reveal-inner">
              <div className="bday-present-reveal-back">
                <img src={cardbackUrl || '/cardback.png'} draggable={false} />
              </div>
              <div className="bday-present-reveal-front">
                {imgUrl ? <img src={imgUrl} draggable={false} />
                  : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg3)', fontSize: 11, color: 'var(--text)', textAlign: 'center', padding: 4 }}>{cardName}</div>}
              </div>
            </div>
          </div>
        );
      })}
    </>
  );
}

// Brackle catapult — single five-phase flying card. THREE chained CSS
// animations (load → fire → discard-fly) with `forwards` fills cover
// the visible flow. The implicit gaps between animations are the
// HOLD (creature parked on Brackle) and IMPACT (creature parked at
// target while the explosion plays) phases — no extra animations
// needed since `forwards` fill keeps the card visibly pinned in
// place across each gap.
function BrackleCatapultCard({ sx, sy, mx, my, ex, ey, dx, dy, cardName, loadMs, holdMs, fireMs, impactMs, discardMs }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  // Each chained animation's `animation-delay` is the cumulative
  // start-time across previous phases. CSS doesn't compute these
  // for us, so we precompute and pass each as a variable.
  const fireDelay    = (loadMs || 0) + (holdMs || 0);
  const discardDelay = fireDelay + (fireMs || 0) + (impactMs || 0);
  return (
    <div className="brackle-catapult-card" style={{
      '--sx': sx + 'px', '--sy': sy + 'px',
      '--mx': mx + 'px', '--my': my + 'px',
      '--ex': ex + 'px', '--ey': ey + 'px',
      '--dx': dx + 'px', '--dy': dy + 'px',
      '--load-ms':     loadMs    + 'ms',
      '--fire-ms':     fireMs    + 'ms',
      '--discard-ms':  discardMs + 'ms',
      '--fire-delay':    fireDelay    + 'ms',
      '--discard-delay': discardDelay + 'ms',
    }}>
      {imgUrl ? <img src={imgUrl} draggable={false} alt="" />
        : <div style={{ width: '100%', height: '100%', background: 'var(--bg3)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 10, color: 'var(--text)', padding: 4, textAlign: 'center' }}>{cardName}</div>}
    </div>
  );
}

function OppDrawAnimCard({ id, startX, startY, endX, endY, cardName, cardbackUrl }) {
  const dx = endX - startX;
  const dy = endY - startY;
  return (
    <div className="draw-anim-card"
      style={{ left: startX, top: startY, '--dx': dx + 'px', '--dy': dy + 'px' }}>
      {cardName ? (
        <BoardCard cardName={cardName} noTooltip />
      ) : (
        <div className="board-card face-down" style={{ width: '100%', height: '100%' }}>
          <img src={cardbackUrl || "/cardback.png"} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
        </div>
      )}
    </div>
  );
}

function DiscardAnimCard({ cardName, startX, startY, endX, endY, dest, delay }) {
  const dx = endX - startX;
  const dy = endY - startY;
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const isDeleted = dest === 'deleted';
  const isDeckReturn = dest === 'deck';
  // `delay` (ms) staggers a simultaneous multi-card batch. The flight
  // keyframes have no backwards fill, so during the delay the card
  // simply sits at its board slot (start position) and then flies —
  // exactly the "wait your turn, then go" cascade we want.
  return (
    <div className={'discard-anim-card' + (isDeleted ? ' discard-anim-deleted' : '') + (isDeckReturn ? ' discard-anim-deck-return' : '')}
      style={{ left: startX, top: startY, '--dx': dx + 'px', '--dy': dy + 'px', animationDelay: delay ? delay + 'ms' : undefined }}>
      <div className="board-card" style={{ width: '100%', height: '100%' }}>
        {imgUrl ? <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover' }} draggable={false} />
        : <div className="board-card-text">{cardName || '?'}</div>}
      </div>
      {isDeleted && <div className="delete-energy-overlay" />}
    </div>
  );
}

// ═══════════════════════════════════════════
//  MODULAR GAME ANIMATION SYSTEM
//  Add new animation types by adding to ANIM_REGISTRY.
//  Usage: playAnimation('explosion', '#target-selector', { duration: 800 })
// ═══════════════════════════════════════════

// Draggable floating panel — used for targeting dialogs, first-choice, etc.
function DraggablePanel({ children, className, style }) {
  const [pos, setPos] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const offsetRef = useRef({ x: 0, y: 0 });
  const panelRef = useRef(null);
  const cleanupRef = useRef(null);
  const onDown = (e) => {
    // Don't start a drag when the pointer-down lands on an interactive
    // form control. `preventDefault()` below would otherwise swallow the
    // native mousedown that opens a <select> dropdown, focuses an <input>,
    // or toggles a checkbox.
    const tag = e.target.tagName;
    if (tag === 'BUTTON' || tag === 'SELECT' || tag === 'OPTION'
        || tag === 'INPUT' || tag === 'TEXTAREA') return;
    const r = panelRef.current?.getBoundingClientRect();
    if (!r) return;
    const pt = window.getPointerXY(e);
    offsetRef.current = { x: pt.x - r.left, y: pt.y - r.top };
    setDragging(true);
    if (e.cancelable) e.preventDefault();
  };
  useEffect(() => {
    if (!dragging) return;
    const cleanup = window.addDragListeners(
      (mx, my) => {
        setPos({ x: mx - offsetRef.current.x, y: my - offsetRef.current.y });
      },
      () => setDragging(false)
    );
    cleanupRef.current = cleanup;
    return cleanup;
  }, [dragging]);
  const hasCustomPos = pos.x !== 0 || pos.y !== 0;
  const posStyle = hasCustomPos
    ? { position: 'fixed', left: pos.x, top: pos.y, transform: 'none' }
    : {};
  return (
    <div ref={panelRef} className={className} style={{ ...style, ...posStyle, cursor: dragging ? 'grabbing' : 'grab' }}
      onMouseDown={onDown} onTouchStart={onDown} onClick={e => e.stopPropagation()}>
      {children}
    </div>
  );
}

// Frozen overlay with animated snowflake particles
function FrozenOverlay() {
  const particles = useMemo(() => Array.from({ length: 14 }, () => ({
    x: 5 + Math.random() * 90,
    y: 5 + Math.random() * 90,
    size: 5 + Math.random() * 7,
    delay: Math.random() * 3,
    dur: 1.5 + Math.random() * 2,
    char: ['❄','❅','❆','✦','✧','·','*'][Math.floor(Math.random() * 7)],
  })), []);
  return (
    <div className="status-frozen-overlay">
      {particles.map((p, i) => (
        <span key={i} className="frozen-particle" style={{
          left: p.x + '%', top: p.y + '%', fontSize: p.size,
          animationDelay: p.delay + 's', animationDuration: p.dur + 's',
        }}>{p.char}</span>
      ))}
    </div>
  );
}

// Immune/Shielded status icon with instant custom tooltip
function ImmuneIcon({ heroName, statusType }) {
  const tooltipKey = statusType === 'shielded' ? 'shielded' : 'immune';
  return (
    <div className={'status-immune-icon' + (statusType === 'shielded' ? ' status-shielded-icon' : '')}
      onMouseEnter={() => { window._immuneTooltip = heroName; window._immuneTooltipType = tooltipKey; window.dispatchEvent(new Event('immuneHover')); }}
      onMouseLeave={() => { window._immuneTooltip = null; window._immuneTooltipType = null; window.dispatchEvent(new Event('immuneHover')); }}>
      🛡️
    </div>
  );
}

// Card reveal — opponent's played card appears centered and expands/fades
function CardRevealOverlay({ reveals, onRemove }) {
  return (
    <div className="card-reveal-stack">
      {reveals.map((rev, idx) => (
        <CardRevealEntry key={rev.id} cardName={rev.cardName} onDone={() => onRemove(rev.id)} />
      ))}
    </div>
  );
}

function CardRevealEntry({ cardName, onDone }) {
  const card = CARDS_BY_NAME[cardName];
  const imgUrl = card ? cardImageUrl(card.name) : null;
  const foilType = card?.foil || null;
  useEffect(() => {
    const t = setTimeout(onDone, 3500);
    return () => { clearTimeout(t); setBoardTooltip(null); }; // Clear tooltip on unmount
  }, []);
  if (!card) return null;
  return (
    <div className="card-reveal-entry"
      onMouseEnter={() => setBoardTooltip(card)} onMouseLeave={() => setBoardTooltip(null)}>
      <div className="card-reveal-card">
        {imgUrl ? (
          <img src={imgUrl} style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: 6,
            border: foilType === 'diamond_rare' ? '3px solid rgba(120,200,255,.7)' : foilType === 'secret_rare' ? '3px solid rgba(255,215,0,.6)' : '2px solid var(--bg4)' }} draggable={false} />
        ) : (
          <div style={{ width: '100%', height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
            background: 'var(--bg3)', borderRadius: 6, border: '2px solid var(--bg4)', padding: 16, textAlign: 'center' }}>
            <div style={{ fontSize: 20, fontWeight: 700, color: typeColor(card.cardType), marginBottom: 8 }}>{card.name}</div>
            <div style={{ fontSize: 14, color: 'var(--text2)' }}>{card.cardType}</div>
          </div>
        )}
      </div>
    </div>
  );
}

function ExplosionEffect({ x, y, opacity }) {
  const particles = useMemo(() => Array.from({ length: 24 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 25 + Math.random() * 55;
    return {
      dx: Math.cos(angle) * speed,
      dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 8,
      color: ['#ff4400','#ff8800','#ffcc00','#ff2200','#ffaa00','#fff'][Math.floor(Math.random() * 6)],
      delay: Math.random() * 80,
      dur: 350 + Math.random() * 400,
    };
  }), []);
  // Optional `opacity` prop — passed through from playAnimation options
  // so callers can dim the burst (Laser Volley wants its impacts more
  // ghostly than a regular hit explosion). Defaults to 1 / fully
  // opaque, preserving every existing caller's look.
  const wrapperOpacity = (typeof opacity === 'number' && opacity >= 0 && opacity <= 1) ? opacity : 1;
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100, opacity: wrapperOpacity }}>
      <div className="anim-explosion-flash" />
      {particles.map((p, i) => (
        <div key={i} className="anim-explosion-particle" style={{
          '--dx': p.dx + 'px', '--dy': p.dy + 'px', '--size': p.size + 'px',
          '--color': p.color, animationDelay: p.delay + 'ms', animationDuration: p.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function FreezeEffect({ x, y, w, h }) {
  // Snowballs from right side + ice crystal burst
  const snowballs = useMemo(() => Array.from({ length: 8 }, (_, i) => ({
    startX: 120 + Math.random() * 40,
    startY: -40 + Math.random() * 40,
    delay: i * 60 + Math.random() * 40,
    dur: 250 + Math.random() * 150,
    size: 6 + Math.random() * 6,
  })), []);
  const crystals = useMemo(() => Array.from({ length: 16 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 15 + Math.random() * 35;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 3 + Math.random() * 7,
      color: ['#aaddff','#88ccff','#cceeFF','#ffffff','#66bbff'][Math.floor(Math.random() * 5)],
      delay: 400 + Math.random() * 200,
      dur: 400 + Math.random() * 300,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      {/* Ice flash */}
      <div className="anim-freeze-flash" />
      {/* Snowballs from right */}
      {snowballs.map((s, i) => (
        <div key={'sb'+i} className="anim-snowball" style={{
          '--startX': s.startX + 'px', '--startY': s.startY + 'px',
          '--size': s.size + 'px',
          animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
      {/* Ice crystal particles */}
      {crystals.map((c, i) => (
        <div key={'cr'+i} className="anim-explosion-particle" style={{
          '--dx': c.dx + 'px', '--dy': c.dy + 'px', '--size': c.size + 'px',
          '--color': c.color, animationDelay: c.delay + 'ms', animationDuration: c.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function ThawEffect({ x, y }) {
  const drips = useMemo(() => Array.from({ length: 12 }, () => ({
    xOff: -20 + Math.random() * 40,
    speed: 30 + Math.random() * 50,
    size: 3 + Math.random() * 5,
    delay: Math.random() * 300,
    dur: 500 + Math.random() * 400,
    color: ['#aaddff','#88ccff','#cceeFF','#ddf4ff'][Math.floor(Math.random() * 4)],
  })), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-thaw-flash" />
      {drips.map((d, i) => (
        <div key={i} className="anim-thaw-drip" style={{
          '--xOff': d.xOff + 'px', '--speed': d.speed + 'px', '--size': d.size + 'px',
          '--color': d.color, animationDelay: d.delay + 'ms', animationDuration: d.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Electric strike — small lightning bolts from all directions converging on target
function ElectricStrikeEffect({ x, y }) {
  const bolts = useMemo(() => Array.from({ length: 16 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 55 + Math.random() * 45;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: 8 + Math.random() * 10,
      delay: Math.random() * 200,
      dur: 150 + Math.random() * 150,
      rotation: (angle * 180 / Math.PI) + 180, // Point toward center
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: 14 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 12 + Math.random() * 30;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5,
      color: ['#ffe033','#fff','#ffcc00','#ffffaa','#ffd700'][Math.floor(Math.random() * 5)],
      delay: 250 + Math.random() * 150,
      dur: 250 + Math.random() * 250,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-electric-flash" />
      {bolts.map((b, i) => (
        <div key={'eb'+i} className="anim-electric-bolt" style={{
          '--startX': b.startX + 'px', '--startY': b.startY + 'px', '--size': b.size + 'px',
          '--rotation': b.rotation + 'deg',
          animationDelay: b.delay + 'ms', animationDuration: b.dur + 'ms',
        }}>⚡</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'es'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Negated overlay — persistent small electricity sparks on the hero
function NegatedOverlay() {
  const sparks = useMemo(() => Array.from({ length: 10 }, () => ({
    x: 8 + Math.random() * 84,
    y: 8 + Math.random() * 84,
    size: 7 + Math.random() * 6,
    delay: Math.random() * 2,
    dur: 0.4 + Math.random() * 0.6,
  })), []);
  return (
    <div className="status-negated-overlay">
      {sparks.map((s, i) => (
        <span key={i} className="negated-spark" style={{
          left: s.x + '%', top: s.y + '%', fontSize: s.size,
          animationDelay: s.delay + 's', animationDuration: s.dur + 's',
        }}>⚡</span>
      ))}
    </div>
  );
}

// Flame strike — fire converging from all directions onto target
// Skeleton Demon's signature attack — black flames engulfing the
// target. Reuses flame_strike's radial-converge structure but with a
// dark-purple palette (CSS filter `brightness(0)` blackens the emoji
// silhouette and the drop-shadow filters paint the violet outer
// glow). `intensity` scales count + size + reach with the damage
// multiplier (50 dmg → intensity 1, 100 dmg → 2, 150 dmg → 3, …).
// Capped at 5 so absurd-multiplier hits still render legibly.
function BlackFlameStrikeEffect({ x, y, intensity = 1 }) {
  const k = Math.min(Math.max(intensity || 1, 1), 5);
  const flameCount = 14 + Math.round(k * 7);
  const sparkCount = 10 + Math.round(k * 4);
  const sizeMult   = 0.85 + k * 0.22;   // 1.07 → 1.95
  const reach      = 50 + k * 16;       // 66   → 130
  const flames = useMemo(() => Array.from({ length: flameCount }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 30 + Math.random() * reach;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: (10 + Math.random() * 14) * sizeMult,
      delay: Math.random() * 220,
      dur: 240 + Math.random() * 200,
      char: ['🔥','🔥','🔥','▲','✦'][Math.floor(Math.random() * 5)],
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: sparkCount }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = (15 + Math.random() * 30) * sizeMult;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5 * sizeMult,
      // Deep-violet / black-purple shrapnel — matches the central
      // flash's palette so all colored bits stay in the same family.
      color: ['#1a0028','#2a0040','#3d0050','#440066','#1f0033'][Math.floor(Math.random() * 5)],
      delay: 320 + Math.random() * 160,
      dur: 320 + Math.random() * 260,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-black-flame-flash" style={{ '--bfScale': sizeMult }} />
      {flames.map((f, i) => (
        <div key={'bfl'+i} className="anim-black-flame-shard" style={{
          '--startX': f.startX + 'px', '--startY': f.startY + 'px', '--size': f.size + 'px',
          animationDelay: f.delay + 'ms', animationDuration: f.dur + 'ms',
        }}>{f.char}</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'bfs'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

function FlameStrikeEffect({ x, y }) {
  const flames = useMemo(() => Array.from({ length: 18 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const dist = 55 + Math.random() * 45;
    return {
      startX: Math.cos(angle) * dist,
      startY: Math.sin(angle) * dist,
      size: 10 + Math.random() * 12,
      delay: Math.random() * 180,
      dur: 200 + Math.random() * 150,
      char: ['🔥','🔥','🔥','✦','·'][Math.floor(Math.random() * 5)],
    };
  }), []);
  const sparks = useMemo(() => Array.from({ length: 12 }, () => {
    const angle = Math.random() * Math.PI * 2;
    const speed = 15 + Math.random() * 30;
    return {
      dx: Math.cos(angle) * speed, dy: Math.sin(angle) * speed,
      size: 2 + Math.random() * 5,
      color: ['#ff4400','#ff8800','#ffcc00','#ff2200','#ffaa00'][Math.floor(Math.random() * 5)],
      delay: 300 + Math.random() * 150,
      dur: 300 + Math.random() * 250,
    };
  }), []);
  return (
    <div style={{ position: 'fixed', left: x, top: y, pointerEvents: 'none', zIndex: 10100 }}>
      <div className="anim-flame-flash" />
      {flames.map((f, i) => (
        <div key={'fl'+i} className="anim-flame-shard" style={{
          '--startX': f.startX + 'px', '--startY': f.startY + 'px', '--size': f.size + 'px',
          animationDelay: f.delay + 'ms', animationDuration: f.dur + 'ms',
        }}>{f.char}</div>
      ))}
      {sparks.map((s, i) => (
        <div key={'fs'+i} className="anim-explosion-particle" style={{
          '--dx': s.dx + 'px', '--dy': s.dy + 'px', '--size': s.size + 'px',
          '--color': s.color, animationDelay: s.delay + 'ms', animationDuration: s.dur + 'ms',
        }} />
      ))}
    </div>
  );
}

// Hand ambiance — an always-on atmospheric layer for the player's OWN hand:
//   • BLOOM: soft player-coloured light rising from the bottom edge of the
//     hand strip, screen-blended over its dark background and gently
//     pulsing. Painted first in DOM order so it sits behind the cards.
//   • PIXEL PARTICLES: sparse pixel motes drifting slowly upward off the
//     hand, tinted the player's colour (plus the odd white sparkle). Kept
//     small + low-opacity so they read as ambient dust, never clutter, and
//     float just above the cards (z-index) so they're actually visible.
// Both layers are pointer-events:none and respect prefers-reduced-motion.
// The colour comes in as the player's chosen colour.
function HandAmbiance({ color }) {
  const motes = useMemo(() => {
    const N = 80;   // doubled from 40 — denser pixel rain over the hand
    const arr = [];
    for (let i = 0; i < N; i++) {
      const dur = 3 + Math.random() * 4;                 // 3–7s drift (snappier)
      arr.push({
        top:   Math.random() * 100,
        left:  Math.random() * 100,
        size:  2 + Math.floor(Math.random() * 3),        // 2–4px pixel squares
        dur,
        delay: -Math.random() * dur,                     // mid-cycle stagger
        dx:    (Math.random() * 2 - 1) * 26,             // -26..26px horizontal drift
        dy:    -(24 + Math.random() * 90),               // rise far enough to leave the hand
        max:   0.22 + Math.random() * 0.3,               // subtle peak opacity
        // Mostly the player's colour; ~30% white for a sparkle.
        color: Math.random() < 0.3 ? '#ffffff' : 'var(--amb-me)',
      });
    }
    return arr;
  }, []);
  return (
    <div className="hand-ambiance" aria-hidden="true"
      style={{ '--amb-me': color || '#00f0ff' }}>
      <div className="hand-bloom" />
      <div className="hand-particles">
        {motes.map((p, i) => (
          <span key={i} className="hand-mote" style={{
            top: p.top + '%', left: p.left + '%',
            '--p-size': p.size + 'px',
            '--p-color': p.color,
            '--p-dur': p.dur + 's',
            '--p-delay': p.delay + 's',
            '--p-dx': p.dx + 'px',
            '--p-dy': p.dy + 'px',
            '--p-max': p.max,
          }} />
        ))}
      </div>
    </div>
  );
}

// Battlefield ambiance — always-on pixel motes drifting upward across the
// whole battlefield background, mirroring the visual language of
// HandAmbiance (small pixel squares, slow rise, subtle opacity) so hand
// and board read as one continuous atmosphere. Differences vs the hand:
//   • BACKGROUND layer: mounted as the FIRST child of .board-center with
//     z-index 0, so every zone / card / area overlay paints on top — the
//     motes stay strictly behind the play field.
//   • OWNERSHIP TINT: motes spawning in the bottom half are tinted the
//     local player's colour, top-half motes the opponent's colour, plus
//     ~25% white sparkles — the ambiance subtly mirrors side ownership.
//   • Dimmer + slower than the hand layer so it never competes with
//     cards for attention.
// pointer-events: none, respects prefers-reduced-motion (see .board-mote).
function BoardAmbiance({ colorMe, colorOpp }) {
  const motes = useMemo(() => {
    const N = 56;
    const arr = [];
    for (let i = 0; i < N; i++) {
      const dur = 4 + Math.random() * 5;                 // 4–9s — calmer than the hand
      const top = Math.random() * 100;
      arr.push({
        top,
        left: Math.random() * 100,
        size: 2 + Math.floor(Math.random() * 3),         // 2–4px pixel squares
        dur,
        delay: -Math.random() * dur,                     // mid-cycle stagger
        dx:   (Math.random() * 2 - 1) * 34,              // -34..34px horizontal drift
        dy:   -(40 + Math.random() * 130),               // long rise across the field
        max:  0.14 + Math.random() * 0.22,               // dim — background layer
        color: Math.random() < 0.25 ? '#ffffff'
             : (top > 50 ? 'var(--amb-board-me)' : 'var(--amb-board-opp)'),
      });
    }
    return arr;
  }, []);
  return (
    <div className="board-ambiance" aria-hidden="true"
      style={{ '--amb-board-me': colorMe || '#00f0ff', '--amb-board-opp': colorOpp || '#ff5577' }}>
      {motes.map((p, i) => (
        <span key={i} className="board-mote" style={{
          top: p.top + '%', left: p.left + '%',
          '--p-size': p.size + 'px',
          '--p-color': p.color,
          '--p-dur': p.dur + 's',
          '--p-delay': p.delay + 's',
          '--p-dx': p.dx + 'px',
          '--p-dy': p.dy + 'px',
          '--p-max': p.max,
        }} />
      ))}
    </div>
  );
}

// Acid Rain overlay — continuous blood-red rain covering the board area
// while an Acid Rain Area card is active in either area zone. Sized via
// position:absolute inset:0 so it fills the .board-center container
// without leaking onto the hand / side panels.
// Deepsea Castle area overlay — split into two layers:
//   • DARKNESS: radial gradient at z-index auto, rendered first inside
//     .board-center so it paints before ALL zones/cards (siblings and
//     their descendants later in DOM stack on top). Empty zones have
//     a semi-transparent bg so the darkness shows through; filled
//     zones with opaque card images naturally cover it.
//   • GODRAYS + motes: z-index 1000, rendered as a sibling above every
//     card and zone. Paints red beams on top of the entire battlefield.
//
// Both layers are pointer-events: none so they never steal clicks.
function DeepseaCastleOverlay() {
  const beams = useMemo(() => Array.from({ length: 9 }, () => ({
    left: Math.random() * 100,
    width: 10 + Math.random() * 26,
    skew: -8 + Math.random() * 16,
    delay: -Math.random() * 4,
    dur: 6 + Math.random() * 4,
    opacityPeak: 0.22 + Math.random() * 0.22,
  })), []);
  const motes = useMemo(() => Array.from({ length: 20 }, () => ({
    x: Math.random() * 100,
    y: Math.random() * 100,
    size: 2 + Math.random() * 2.5,
    delay: -Math.random() * 6,
    dur: 4 + Math.random() * 5,
  })), []);
  return (
    <>
      {/* LAYER 1 — DARKNESS (beneath all cards + zones). */}
      <div className="deepsea-castle-darkness" style={{
        position: 'absolute', inset: 0, pointerEvents: 'none',
        overflow: 'hidden',
        background: 'radial-gradient(ellipse at center top, rgba(20,0,5,0.35) 0%, rgba(5,0,2,0.55) 70%, rgba(0,0,0,0.6) 100%)',
      }} />
      {/* LAYER 2 — GODRAYS + motes (above all cards + zones). z-index
          1000 wins over zone-has-card (z 10) and any standard board-
          layer stacking, while staying BELOW hand (z 10000) and
          modal/popup overlays (z 90000+) so UI stays usable. */}
      <div className="deepsea-castle-rays" style={{
        position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 1000,
        overflow: 'hidden',
      }}>
        {beams.map((b, i) => (
          <span key={'b' + i} style={{
            position: 'absolute',
            left: b.left + '%', top: '-10%',
            width: b.width + 'px', height: '130%',
            transform: 'skewX(' + b.skew + 'deg)',
            transformOrigin: 'top center',
            background: 'linear-gradient(180deg, rgba(255,40,60,' + b.opacityPeak + ') 0%, rgba(180,10,25,' + (b.opacityPeak * 0.7) + ') 40%, rgba(80,0,10,0) 100%)',
            filter: 'blur(6px)',
            mixBlendMode: 'screen',
            animation: 'deepseaCastleBeam ' + b.dur + 's ease-in-out ' + b.delay + 's infinite',
          }} />
        ))}
        {motes.map((m, i) => (
          <span key={'m' + i} style={{
            position: 'absolute',
            left: m.x + '%', top: m.y + '%',
            width: m.size + 'px', height: m.size + 'px',
            borderRadius: '50%',
            background: 'rgba(255,80,100,0.85)',
            boxShadow: '0 0 6px rgba(255,40,60,0.9)',
            animation: 'deepseaCastleMote ' + m.dur + 's ease-in-out ' + m.delay + 's infinite',
          }} />
        ))}
        <style>{`
          @keyframes deepseaCastleBeam {
            0%, 100% { opacity: 0.35; transform: translateX(0) skewX(var(--skew, 0deg)); }
            50%      { opacity: 1;    transform: translateX(6px) skewX(var(--skew, 0deg)); }
          }
          @keyframes deepseaCastleMote {
            0%   { opacity: 0; transform: translateY(0) scale(0.6); }
            25%  { opacity: 0.85; }
            100% { opacity: 0; transform: translateY(-40px) scale(1); }
          }
        `}</style>
      </div>
    </>
  );
}

// Slippery Ice — a translucent frosted sheet pinned UNDER the zones and
// cards (zIndex omitted → default auto, lower than zone-has-card's 10),
// plus a swarm of slow cold-white sparkles that glint across the sheet
// like sun catching ice crystals. The sparkles sit in the same under-
// cards layer so they peek through gaps between zones rather than
// glittering on top of artwork.
function SlipperyIceOverlay() {
  const sparkles = useMemo(() => Array.from({ length: 48 }, () => ({
    x: Math.random() * 100,
    y: Math.random() * 100,
    size: 1.5 + Math.random() * 3,
    delay: -Math.random() * 3.4,
    dur: 1.8 + Math.random() * 2.6,
    // A fraction of sparkles use the 4-pointed "star glint" shape; the
    // rest are round glitter points. The split reads as a mix of "light
    // catching a facet" vs "tiny snow dust".
    star: Math.random() < 0.3,
  })), []);
  const cracks = useMemo(() => Array.from({ length: 8 }, () => ({
    x: Math.random() * 100,
    y: 10 + Math.random() * 80,
    len: 30 + Math.random() * 60,
    rot: -20 + Math.random() * 40,
    opacity: 0.08 + Math.random() * 0.1,
  })), []);
  return (
    <div className="slippery-ice-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
      // Pale cyan-tinted frost sheet. The radial gradient fakes a
      // soft "centre of the rink" highlight; the top linear layer adds
      // a faint sky-reflection. mixBlendMode 'screen' keeps it readable
      // over both the light and dark areas of the playmat.
      background:
        'radial-gradient(ellipse at 50% 55%, rgba(220,245,255,0.22) 0%, rgba(180,225,245,0.14) 55%, rgba(120,195,225,0.10) 100%),'
        + 'linear-gradient(180deg, rgba(230,250,255,0.10) 0%, rgba(180,220,240,0.04) 100%)',
      mixBlendMode: 'screen',
    }}>
      {cracks.map((c, i) => (
        <span key={'crack' + i} style={{
          position: 'absolute',
          left: c.x + '%', top: c.y + '%',
          width: c.len + 'px', height: '1px',
          background: 'linear-gradient(90deg, transparent 0%, rgba(255,255,255,' + c.opacity + ') 50%, transparent 100%)',
          transform: 'rotate(' + c.rot + 'deg)',
          filter: 'blur(0.4px)',
        }} />
      ))}
      {sparkles.map((s, i) => (
        <span key={'spk' + i} style={{
          position: 'absolute',
          left: s.x + '%', top: s.y + '%',
          width: s.size + 'px', height: s.size + 'px',
          transform: 'translate(-50%, -50%)',
          background: s.star
            ? 'transparent'
            : 'radial-gradient(circle, rgba(255,255,255,1) 0%, rgba(220,245,255,0.85) 45%, rgba(180,225,245,0) 100%)',
          borderRadius: '50%',
          boxShadow: s.star
            ? ''
            : '0 0 ' + (s.size * 2.5) + 'px rgba(200,240,255,0.9), 0 0 ' + (s.size * 5) + 'px rgba(150,210,240,0.5)',
          animation: 'slipperyIceSparkle ' + s.dur + 's ease-in-out ' + s.delay + 's infinite',
        }}>
          {s.star && (
            <span style={{
              position: 'absolute', inset: 0,
              background:
                'linear-gradient(0deg, transparent 45%, rgba(255,255,255,1) 49%, rgba(255,255,255,1) 51%, transparent 55%),'
                + 'linear-gradient(90deg, transparent 45%, rgba(255,255,255,1) 49%, rgba(255,255,255,1) 51%, transparent 55%)',
              filter: 'blur(0.4px)',
              boxShadow: '0 0 ' + (s.size * 3) + 'px rgba(200,240,255,0.9)',
            }} />
          )}
        </span>
      ))}
      <style>{`
        @keyframes slipperyIceSparkle {
          0%, 100% { opacity: 0; transform: translate(-50%, -50%) scale(0.4); }
          45%      { opacity: 1; transform: translate(-50%, -50%) scale(1.15); }
          55%      { opacity: 1; transform: translate(-50%, -50%) scale(1);    }
          75%      { opacity: 0.25; transform: translate(-50%, -50%) scale(0.85); }
        }
      `}</style>
    </div>
  );
}

// The Cosmic Depths — a black starfield pinned under the zones and
// cards (same z-index convention as Slippery Ice). The dark cosmos
// backdrop is its own layer; the stars render in a SEPARATE layer
// above it with no blend mode so the whites stay bright. (The earlier
// version stacked them in a single `mixBlendMode: multiply` div, which
// multiplied every white star against the background and made the
// twinkle lattice vanish entirely.)
function CosmicDepthsOverlay() {
  const stars = useMemo(() => Array.from({ length: 140 }, () => ({
    x: Math.random() * 100,
    y: Math.random() * 100,
    // Mostly tiny specks; a few bigger to add depth.
    size: 1.2 + Math.pow(Math.random(), 3) * 3.2,
    delay: -Math.random() * 4.2,
    dur: 2.2 + Math.random() * 3.6,
    // A fraction become 4-pointed "sparkle" glints; the rest are round.
    sparkle: Math.random() < 0.35,
  })), []);
  return (
    <div className="cosmic-depths-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
    }}>
      {/* Layer 1: deep cosmos gradient. Solid-opaque so the stars read
          on true black; no blend mode (an earlier multiply blend
          zeroed out white stars on top). */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'radial-gradient(ellipse at 50% 50%, rgba(22,14,50,0.96) 0%, rgba(8,5,22,0.98) 55%, rgba(0,0,0,1) 100%)',
      }} />
      {/* Layer 2: star field on its own. `mixBlendMode: screen` keeps
          the whites bright even if a future theme tints the layer
          beneath (screen of white + anything = white). */}
      <div style={{
        position: 'absolute', inset: 0,
        mixBlendMode: 'screen',
      }}>
        {stars.map((s, i) => (
          <span key={'star' + i} style={{
            position: 'absolute',
            left: s.x + '%', top: s.y + '%',
            width: s.size + 'px', height: s.size + 'px',
            transform: 'translate(-50%, -50%)',
            background: s.sparkle
              ? 'transparent'
              : 'radial-gradient(circle, rgba(255,255,255,1) 0%, rgba(230,235,255,0.95) 45%, rgba(200,210,255,0) 100%)',
            borderRadius: '50%',
            boxShadow: s.sparkle
              ? ''
              : '0 0 ' + (s.size * 2.5) + 'px rgba(255,255,255,0.95), 0 0 ' + (s.size * 6) + 'px rgba(180,200,255,0.45)',
            animation: 'cosmicDepthsTwinkle ' + s.dur + 's ease-in-out ' + s.delay + 's infinite',
          }}>
            {s.sparkle && (
              <span style={{
                position: 'absolute', inset: 0,
                background:
                  'linear-gradient(0deg, transparent 44%, rgba(255,255,255,1) 49%, rgba(255,255,255,1) 51%, transparent 56%),'
                  + 'linear-gradient(90deg, transparent 44%, rgba(255,255,255,1) 49%, rgba(255,255,255,1) 51%, transparent 56%)',
                filter: 'blur(0.4px)',
                boxShadow: '0 0 ' + (s.size * 3) + 'px rgba(255,255,255,0.95)',
              }} />
            )}
          </span>
        ))}
      </div>
      <style>{`
        @keyframes cosmicDepthsTwinkle {
          0%, 100% { opacity: 0.2; transform: translate(-50%, -50%) scale(0.7); }
          50%      { opacity: 1;   transform: translate(-50%, -50%) scale(1.2); }
        }
      `}</style>
    </div>
  );
}

// Graveyard of Limited Power — dark cemetery backdrop. Tombstones are
// scattered randomly across the lower half of the screen; each carries
// a pulsing red light. Random positions / sizes / tilts are seeded once
// per mount via useMemo so the layout doesn't reshuffle on every render.
function GraveyardOfLimitedPowerOverlay() {
  const tombstones = useMemo(() => Array.from({ length: 24 }, () => ({
    x: Math.random() * 100,
    y: 32 + Math.random() * 62,
    scale: 0.7 + Math.random() * 0.85,
    tilt: -10 + Math.random() * 20,
    delay: -Math.random() * 3,
    dur: 1.6 + Math.random() * 1.6,
  })), []);
  return (
    <div className="graveyard-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
    }}>
      {/* Layer 1: dark, fog-tinted sky with a faint blood-red horizon. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'radial-gradient(ellipse at 50% 100%, rgba(72,12,18,0.78) 0%, rgba(22,10,18,0.92) 45%, rgba(6,4,8,0.97) 100%)',
      }} />
      {/* Layer 2: ground silhouette mound at the bottom edge. */}
      <div style={{
        position: 'absolute', left: 0, right: 0, bottom: 0, height: '34%',
        background:
          'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(8,4,8,0.6) 55%, rgba(0,0,0,0.88) 100%)',
      }} />
      {/* Layer 3: tombstones with red lights. */}
      {tombstones.map((t, i) => {
        const w = 16 * t.scale;
        const h = 26 * t.scale;
        return (
          <div key={'tomb' + i} style={{
            position: 'absolute',
            left: t.x + '%', top: t.y + '%',
            width: w + 'px', height: h + 'px',
            transform: 'translate(-50%, -50%) rotate(' + t.tilt + 'deg)',
          }}>
            <div style={{
              position: 'absolute', inset: 0,
              background: 'linear-gradient(180deg, #2c2630 0%, #1a161e 75%, #100a10 100%)',
              borderRadius: (w * 0.5) + 'px ' + (w * 0.5) + 'px 2px 2px',
              boxShadow: 'inset 0 -2px 4px rgba(0,0,0,0.7), 0 4px 8px rgba(0,0,0,0.55)',
            }} />
            <span style={{
              position: 'absolute',
              left: '50%', top: '40%',
              width: (w * 0.32) + 'px', height: (w * 0.32) + 'px',
              transform: 'translate(-50%, -50%)',
              background:
                'radial-gradient(circle, rgba(255,40,40,1) 0%, rgba(180,20,20,0.7) 50%, rgba(120,0,0,0) 100%)',
              borderRadius: '50%',
              boxShadow:
                '0 0 ' + (w * 0.7) + 'px rgba(255,30,30,0.85), '
                + '0 0 ' + (w * 1.5) + 'px rgba(255,0,0,0.5)',
              animation: 'graveyardLightPulse ' + t.dur + 's ease-in-out ' + t.delay + 's infinite',
            }} />
          </div>
        );
      })}
      <style>{`
        @keyframes graveyardLightPulse {
          0%, 100% { opacity: 0.4; transform: translate(-50%, -50%) scale(0.85); }
          50%      { opacity: 1.0; transform: translate(-50%, -50%) scale(1.18); }
        }
      `}</style>
    </div>
  );
}

// The First Circle of Hell — gray wasteland: ash-gray sky fading to
// a dark, lifeless ground with scattered rubble silhouettes and
// drifting ash particles. Deliberately low-saturation and static —
// the card's identity is "everything here is dust" rather than
// anything dramatic.
function FirstCircleOfHellOverlay() {
  const rubble = useMemo(() => Array.from({ length: 22 }, () => ({
    x: Math.random() * 100,
    y: 56 + Math.random() * 38,
    scale: 0.6 + Math.random() * 1.2,
    tilt: -28 + Math.random() * 56,
    // Three rough silhouette shapes — picked at random per piece so
    // the wasteland reads as varied rubble rather than identical
    // tombstones.
    shape: Math.floor(Math.random() * 3),
    shade: 16 + Math.floor(Math.random() * 18),
  })), []);
  const ashes = useMemo(() => Array.from({ length: 18 }, () => ({
    x: Math.random() * 100,
    delay: -Math.random() * 14,
    dur: 10 + Math.random() * 14,
    drift: -16 + Math.random() * 32,
    size: 2 + Math.random() * 3,
    opacity: 0.18 + Math.random() * 0.32,
  })), []);
  return (
    <div className="first-circle-of-hell-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', overflow: 'hidden',
    }}>
      {/* Layer 1: ash-gray sky. Deliberately desaturated so the
          wasteland reads cold and joyless. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'linear-gradient(180deg, rgba(56,56,62,0.78) 0%, rgba(40,40,46,0.86) 45%, rgba(22,22,26,0.92) 100%)',
      }} />
      {/* Layer 2: lighter ashen haze across the middle band. */}
      <div style={{
        position: 'absolute', left: 0, right: 0, top: '36%', height: '28%',
        background:
          'linear-gradient(180deg, rgba(80,78,82,0.0) 0%, rgba(110,108,112,0.22) 50%, rgba(80,78,82,0.0) 100%)',
        mixBlendMode: 'screen',
      }} />
      {/* Layer 3: cracked-earth ground silhouette. */}
      <div style={{
        position: 'absolute', left: 0, right: 0, bottom: 0, height: '38%',
        background:
          'linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(20,20,24,0.55) 40%, rgba(8,8,10,0.92) 100%)',
      }} />
      {/* Layer 4: scattered rubble silhouettes — three jagged shapes.
          Solid dark blocks with uneven clip-paths to suggest broken
          stones. No glow; this is dead earth. */}
      {rubble.map((r, i) => {
        const w = 18 * r.scale;
        const h = 14 * r.scale;
        const clip = r.shape === 0
          ? 'polygon(20% 100%, 0% 35%, 28% 0%, 70% 12%, 100% 60%, 80% 100%)'
          : r.shape === 1
            ? 'polygon(0% 100%, 15% 20%, 50% 0%, 90% 28%, 100% 100%)'
            : 'polygon(10% 100%, 0% 50%, 35% 8%, 80% 22%, 100% 80%, 60% 100%)';
        const tone = `rgb(${r.shade}, ${r.shade}, ${r.shade + 4})`;
        return (
          <div key={'rb' + i} style={{
            position: 'absolute',
            left: r.x + '%', top: r.y + '%',
            width: w + 'px', height: h + 'px',
            transform: 'translate(-50%, -50%) rotate(' + r.tilt + 'deg)',
            background: tone,
            clipPath: clip,
            boxShadow: 'inset 0 -1px 2px rgba(0,0,0,0.6)',
          }} />
        );
      })}
      {/* Layer 5: slow drifting ash particles. Use simple round
          divs that float gently upward; the slow loop makes the
          air feel "stale" rather than energetic. */}
      {ashes.map((a, i) => (
        <div key={'ash' + i} style={{
          position: 'absolute',
          left: a.x + '%', top: '102%',
          width: a.size + 'px', height: a.size + 'px',
          borderRadius: '50%',
          background: 'rgba(180,180,184,1)',
          opacity: a.opacity,
          ['--drift']: a.drift + 'px',
          animation: 'firstCircleAshFloat ' + a.dur + 's linear ' + a.delay + 's infinite',
        }} />
      ))}
      <style>{`
        @keyframes firstCircleAshFloat {
          0%   { transform: translate(0, 0); opacity: 0; }
          15%  { opacity: var(--ashOpacity, 1); }
          90%  { opacity: var(--ashOpacity, 1); }
          100% { transform: translate(var(--drift, 0), -120vh); opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// Spider Hive — a dusty cobwebbed corner of the battlefield. Pale
// silken arcs spider out from each corner (SVG concentric radials),
// a few long strands drape diagonally across the middle, and a
// handful of tiny pixel-spiders crawl along independent looped paths.
// The whole layer sits under the cards (no zIndex set — defaults to
// auto, lower than the zone-has-card layer's z:10).
function SpiderHiveOverlay() {
  // Stable per-mount randomization for the spiders so they don't
  // re-randomize every render.
  const spiders = useMemo(() => Array.from({ length: 6 }, (_, i) => {
    // Each spider gets a unique path along an ellipse-ish curve so
    // they wander independently rather than marching in lockstep.
    const dur = 9 + Math.random() * 7; // seconds for a full loop
    const delay = -Math.random() * dur;
    const size = 12 + Math.random() * 6; // SVG-side radius; rendered size is size*2 px wide
    // Loop centre — kept away from the corners (the corner webs
    // already live there) and inset from the edges so the wander
    // arcs don't sail off the playmat.
    const cx = 18 + Math.random() * 64;
    const cy = 18 + Math.random() * 64;
    // Wander radii are generous so the motion reads from across the
    // board, not a tight twitch. % of parent — see the `left`/`top`
    // animation comment for why that matters.
    const rx = 14 + Math.random() * 18;
    const ry = 10 + Math.random() * 14;
    return { id: i, dur, delay, size, cx, cy, rx, ry,
      reverse: Math.random() < 0.5,
      bob: 1.6 + Math.random() * 1.4 };
  }), []);

  // Long diagonal strands drifting across the middle.
  const strands = useMemo(() => Array.from({ length: 5 }, () => ({
    x1: Math.random() * 100, y1: Math.random() * 100,
    x2: Math.random() * 100, y2: Math.random() * 100,
    opacity: 0.10 + Math.random() * 0.12,
  })), []);

  // Each corner web: concentric arcs (silken filaments) + radial spokes.
  const renderCornerWeb = (anchor) => {
    // anchor: 'tl' | 'tr' | 'bl' | 'br' → controls the SVG flip /
    // position of the radial origin.
    const isRight = anchor === 'tr' || anchor === 'br';
    const isBottom = anchor === 'bl' || anchor === 'br';
    // Radial spokes from (0,0) to a fan of endpoints.
    const ARC_COUNT = 7;     // concentric webs
    const SPOKE_COUNT = 9;   // radial threads
    const MAX_R = 220;       // pixel radius of the largest arc
    const spokes = [];
    for (let i = 0; i < SPOKE_COUNT; i++) {
      const angle = (Math.PI / 2) * (i / (SPOKE_COUNT - 1));
      const ex = Math.cos(angle) * MAX_R;
      const ey = Math.sin(angle) * MAX_R;
      spokes.push({ x: ex, y: ey });
    }
    const arcs = [];
    for (let i = 1; i <= ARC_COUNT; i++) {
      const r = (MAX_R / ARC_COUNT) * i;
      arcs.push(r);
    }
    return (
      <svg
        viewBox={`0 0 ${MAX_R} ${MAX_R}`}
        preserveAspectRatio="none"
        style={{
          position: 'absolute',
          [isRight ? 'right' : 'left']: 0,
          [isBottom ? 'bottom' : 'top']: 0,
          width: '32%', height: '40%',
          opacity: 0.55,
          transform:
            (isRight ? 'scaleX(-1) ' : '')
            + (isBottom ? 'scaleY(-1) ' : ''),
          filter: 'drop-shadow(0 0 1px rgba(255,255,255,0.18))',
          pointerEvents: 'none',
        }}>
        {arcs.map((r, i) => (
          <path key={'arc' + i}
            d={`M ${r} 0 A ${r} ${r} 0 0 1 0 ${r}`}
            fill="none"
            stroke="rgba(220,225,235,0.55)"
            strokeWidth={0.7}
          />
        ))}
        {spokes.map((s, i) => (
          <line key={'spoke' + i}
            x1={0} y1={0} x2={s.x} y2={s.y}
            stroke="rgba(220,225,235,0.45)"
            strokeWidth={0.6}
          />
        ))}
      </svg>
    );
  };

  return (
    <div className="spider-hive-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
      // Dusty, faintly bruised tint over the playmat — gives the web
      // structure a contrasting backdrop.
      background:
        'radial-gradient(ellipse at 50% 55%, rgba(40,30,45,0.18) 0%, rgba(20,15,25,0.12) 60%, rgba(0,0,0,0.06) 100%),'
        + 'linear-gradient(180deg, rgba(50,40,55,0.10) 0%, rgba(20,15,25,0.06) 100%)',
      mixBlendMode: 'multiply',
    }}>
      {/* Four corner webs */}
      {renderCornerWeb('tl')}
      {renderCornerWeb('tr')}
      {renderCornerWeb('bl')}
      {renderCornerWeb('br')}

      {/* Long diagonal strands drifting across the middle. Pure SVG
          lines with faint glow — they read as drape silk between the
          corner webs. */}
      <svg viewBox="0 0 100 100" preserveAspectRatio="none" style={{
        position: 'absolute', inset: 0, width: '100%', height: '100%',
        opacity: 0.9, pointerEvents: 'none',
      }}>
        {strands.map((s, i) => (
          <line key={'strand' + i}
            x1={s.x1} y1={s.y1} x2={s.x2} y2={s.y2}
            stroke={`rgba(220,225,235,${s.opacity})`}
            strokeWidth={0.18}
            strokeLinecap="round"
          />
        ))}
      </svg>

      {/* Crawling spiders. Each runs its own elliptical loop, sized
          and timed independently so the swarm reads as wandering
          rather than choreographed.

          IMPORTANT: positional animation uses `left`/`top` rather than
          `transform: translate(%)`. Percentage values on `transform`
          translate are relative to the ELEMENT'S OWN size (≈20px for
          the spider SVG) — that would clamp every spider to a tiny
          arc near top-left. `left`/`top` percentages ARE relative to
          the parent overlay, so the elliptical wander loop spans the
          actual playmat. */}
      {spiders.map(s => (
        <div key={'sp' + s.id}
          style={{
            position: 'absolute',
            // CSS custom props pipe the per-spider params into the
            // shared keyframes definition.
            '--cx': s.cx + '%',
            '--cy': s.cy + '%',
            '--rx': s.rx + '%',
            '--ry': s.ry + '%',
            '--dur': s.dur + 's',
            '--delay': s.delay + 's',
            // Initial position (also where the first keyframe lands so
            // there's no jump when the animation starts).
            left: `calc(${s.cx}% + ${s.rx}%)`,
            top: `${s.cy}%`,
            width: 0, height: 0,
            animation: `spiderHiveWander var(--dur) ease-in-out var(--delay) infinite ${s.reverse ? 'reverse' : 'normal'}`,
          }}>
          {/* The spider itself — body + 8 legs. The wrapper's left/top
              points at the wander-loop position; the SVG's
              `translate(-50%, -50%)` then centers the spider on that
              point. The bob rotation composes on top of the centering
              translate. */}
          <svg
            viewBox="-20 -20 40 40"
            width={s.size * 2} height={s.size * 2}
            style={{
              position: 'absolute',
              left: 0, top: 0,
              transform: 'translate(-50%, -50%)',
              animation: 'spiderHiveBob 0.45s ease-in-out infinite alternate',
              filter: 'drop-shadow(0 1px 1px rgba(0,0,0,0.55))',
            }}>
            {/* Legs (4 pairs, slight curves) */}
            {[-50, -25, 25, 50].map((angle, li) => {
              const a = (angle * Math.PI) / 180;
              const x1 = Math.cos(a) * 4, y1 = Math.sin(a) * 4;
              const x2 = Math.cos(a) * 14, y2 = Math.sin(a) * 14;
              // Bend each leg slightly upward at the knee.
              const kneeAngle = a - 0.35;
              const kx = Math.cos(kneeAngle) * 9, ky = Math.sin(kneeAngle) * 9;
              return (
                <g key={'leg' + li}>
                  <polyline
                    points={`${-x1},${y1} ${-kx},${ky} ${-x2},${y2}`}
                    fill="none" stroke="rgba(20,15,25,0.95)"
                    strokeWidth={1.4} strokeLinecap="round"
                  />
                  <polyline
                    points={`${x1},${y1} ${kx},${ky} ${x2},${y2}`}
                    fill="none" stroke="rgba(20,15,25,0.95)"
                    strokeWidth={1.4} strokeLinecap="round"
                  />
                </g>
              );
            })}
            {/* Body */}
            <ellipse cx={0} cy={0} rx={5.5} ry={4}
              fill="rgba(20,15,25,1)" stroke="rgba(45,30,50,1)" strokeWidth={0.6} />
            {/* Tiny eye dots */}
            <circle cx={-1.6} cy={-1.2} r={0.7} fill="rgba(220,60,60,0.95)" />
            <circle cx={1.6} cy={-1.2} r={0.7} fill="rgba(220,60,60,0.95)" />
          </svg>
        </div>
      ))}

      <style>{`
        @keyframes spiderHiveWander {
          0%   { left: calc(var(--cx) + var(--rx)); top: var(--cy); }
          25%  { left: var(--cx); top: calc(var(--cy) + var(--ry)); }
          50%  { left: calc(var(--cx) - var(--rx)); top: var(--cy); }
          75%  { left: var(--cx); top: calc(var(--cy) - var(--ry)); }
          100% { left: calc(var(--cx) + var(--rx)); top: var(--cy); }
        }
        @keyframes spiderHiveBob {
          0%   { transform: translate(-50%, -50%) rotate(-6deg); }
          100% { transform: translate(-50%, -50%) rotate(6deg); }
        }
      `}</style>
    </div>
  );
}

// Temple of Sacrifice — a wall of gilded golden bricks. A brick-offset
// grid of gold blocks (seeded jitter so the masonry reads as hand-laid,
// not tiled) over dark mortar, with a warm ambient glow that slowly
// shimmers. Static masonry keeps it cheap; only the glow pulses.
function TempleOfSacrificeOverlay() {
  const COLS = 11;
  const ROWS = 8;
  const bricks = useMemo(() => {
    const out = [];
    for (let r = 0; r < ROWS; r++) {
      const offset = (r % 2) * (50 / COLS); // half-cell shift on odd rows
      for (let c = 0; c < COLS; c++) {
        const lum = 150 + Math.floor(Math.random() * 70); // gold luminance range
        out.push({
          x: (c * (100 / COLS)) + offset + (Math.random() * 2 - 1),
          y: (r * (100 / ROWS)) + (Math.random() * 2 - 1),
          w: (100 / COLS) * (0.88 + Math.random() * 0.12),
          h: (100 / ROWS) * (0.84 + Math.random() * 0.16),
          tilt: -3 + Math.random() * 6,
          // Warm gilded tone — strong red+green, low blue = gold.
          tone: `rgb(${lum + 30}, ${Math.round(lum * 0.78)}, ${Math.round(lum * 0.18)})`,
          radius: 10 + Math.random() * 12,
        });
      }
    }
    return out;
  }, []);
  return (
    <div className="temple-of-sacrifice-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', overflow: 'hidden',
    }}>
      <style>{`@keyframes templeGoldGlow { 0%,100% { opacity: 0.6 } 50% { opacity: 1 } }`}</style>
      {/* Layer 1: dark mortar base showing through the seams. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'linear-gradient(180deg, rgba(60,42,10,0.97) 0%, rgba(42,28,6,0.98) 55%, rgba(26,16,2,0.99) 100%)',
      }} />
      {/* Layer 2: the golden bricks. */}
      {bricks.map((b, i) => (
        <div key={'gbrick' + i} style={{
          position: 'absolute',
          left: b.x + '%', top: b.y + '%',
          width: b.w + '%', height: b.h + '%',
          transform: 'rotate(' + b.tilt + 'deg)',
          background: 'linear-gradient(150deg, ' + b.tone + ' 0%, rgba(120,80,12,0.96) 100%)',
          borderRadius: b.radius + '%',
          boxShadow:
            'inset 0 2px 4px rgba(255,245,200,0.45), '
            + 'inset 0 -4px 6px rgba(70,44,4,0.7), '
            + '0 2px 4px rgba(0,0,0,0.5)',
        }} />
      ))}
      {/* Layer 3: warm gilded glow + slow shimmer (screen blend so it
          brightens the gold rather than washing it out). */}
      <div style={{
        position: 'absolute', inset: 0, mixBlendMode: 'screen',
        background:
          'radial-gradient(ellipse at 50% 38%, rgba(255,210,90,0.30) 0%, '
          + 'rgba(200,150,30,0.12) 45%, rgba(0,0,0,0) 78%)',
        animation: 'templeGoldGlow 4.5s ease-in-out infinite',
      }} />
    </div>
  );
}

// Blood Rock — a grimy cobblestone courtyard soaked in blood. A
// brick-offset grid of rounded stones (seeded jitter so the masonry
// reads as hand-laid, not tiled), dark blood pooling into the grout
// lines, irregular splatter blotches with a slow wet sheen, and a
// red ambient vignette. Static masonry (no per-frame animation) keeps
// it cheap; only the blood sheen pulses.
function BloodRockOverlay() {
  // Brick-offset stone grid. Odd rows are shifted half a cell so the
  // seams stagger like real cobblestone. Each stone carries its own
  // shade / size / tilt jitter, frozen once per mount.
  const COLS = 11;
  const ROWS = 8;
  const stones = useMemo(() => {
    const out = [];
    for (let r = 0; r < ROWS; r++) {
      const offset = (r % 2) * (50 / COLS); // half-cell shift on odd rows
      for (let c = 0; c < COLS; c++) {
        const shade = 38 + Math.floor(Math.random() * 26); // gray-brown range
        out.push({
          x: (c * (100 / COLS)) + offset + (Math.random() * 2 - 1),
          y: (r * (100 / ROWS)) + (Math.random() * 2 - 1),
          w: (100 / COLS) * (0.86 + Math.random() * 0.16),
          h: (100 / ROWS) * (0.82 + Math.random() * 0.2),
          tilt: -7 + Math.random() * 14,
          // Warm grimy stone with a faint red staining baked in.
          tone: `rgb(${shade + 6}, ${shade}, ${shade - 4})`,
          radius: 38 + Math.random() * 22,
        });
      }
    }
    return out;
  }, []);
  // Large soft blood pools that sink into the masonry (multiply blend).
  const pools = useMemo(() => Array.from({ length: 6 }, () => ({
    x: 8 + Math.random() * 84,
    y: 24 + Math.random() * 68,
    r: 70 + Math.random() * 130,
    a: 0.5 + Math.random() * 0.35,
  })), []);
  // Irregular splatter blotches — jagged clip-path shapes, bright at
  // the core fading to dark, each with a ring of droplet specks.
  const splatters = useMemo(() => Array.from({ length: 13 }, (_, i) => ({
    x: Math.random() * 100,
    y: 18 + Math.random() * 78,
    s: 26 + Math.random() * 60,
    rot: Math.random() * 360,
    delay: -Math.random() * 4,
    dur: 3 + Math.random() * 2.5,
    shape: i % 3,
    drops: Array.from({ length: 5 + Math.floor(Math.random() * 5) }, () => ({
      a: Math.random() * Math.PI * 2,
      d: 0.6 + Math.random() * 0.7,
      sz: 2 + Math.random() * 4,
    })),
  })), []);
  const clipFor = (shape) => shape === 0
    ? 'polygon(50% 0%, 68% 22%, 100% 38%, 74% 58%, 86% 100%, 50% 74%, 16% 100%, 26% 58%, 0% 36%, 32% 22%)'
    : shape === 1
      ? 'polygon(48% 4%, 80% 12%, 96% 46%, 78% 70%, 92% 96%, 54% 80%, 22% 98%, 8% 62%, 18% 28%)'
      : 'polygon(50% 2%, 72% 18%, 98% 30%, 82% 52%, 100% 82%, 64% 70%, 44% 100%, 30% 66%, 2% 54%, 22% 24%)';
  return (
    <div className="blood-rock-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', overflow: 'hidden',
    }}>
      {/* Layer 1: grimy stone ground base — the grout/mortar showing
          through the gaps between cobbles. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'linear-gradient(180deg, rgba(34,28,26,0.97) 0%, rgba(24,19,18,0.98) 55%, rgba(14,10,10,0.99) 100%)',
      }} />
      {/* Layer 2: the cobblestones. */}
      {stones.map((s, i) => (
        <div key={'cob' + i} style={{
          position: 'absolute',
          left: s.x + '%', top: s.y + '%',
          width: s.w + '%', height: s.h + '%',
          transform: 'rotate(' + s.tilt + 'deg)',
          background: s.tone,
          borderRadius: s.radius + '%',
          boxShadow:
            'inset 0 2px 3px rgba(255,235,225,0.07), '
            + 'inset 0 -3px 5px rgba(0,0,0,0.6), '
            + '0 2px 4px rgba(0,0,0,0.55)',
        }} />
      ))}
      {/* Layer 3: blood pooling into the masonry (multiply so it
          stains the stones rather than sitting on top). */}
      <div style={{
        position: 'absolute', inset: 0, mixBlendMode: 'multiply',
      }}>
        {pools.map((p, i) => (
          <div key={'pool' + i} style={{
            position: 'absolute',
            left: p.x + '%', top: p.y + '%',
            width: p.r + 'px', height: (p.r * 0.7) + 'px',
            transform: 'translate(-50%, -50%)',
            background:
              'radial-gradient(ellipse, rgba(120,4,10,' + p.a + ') 0%, '
              + 'rgba(78,2,8,' + (p.a * 0.7) + ') 45%, rgba(40,0,4,0) 78%)',
            borderRadius: '50%',
          }} />
        ))}
      </div>
      {/* Layer 4: splatter blotches with a wet sheen + droplet specks. */}
      {splatters.map((sp, i) => (
        <div key={'spl' + i} style={{
          position: 'absolute',
          left: sp.x + '%', top: sp.y + '%',
          width: sp.s + 'px', height: sp.s + 'px',
          transform: 'translate(-50%, -50%) rotate(' + sp.rot + 'deg)',
        }}>
          <div style={{
            position: 'absolute', inset: 0,
            background:
              'radial-gradient(circle at 42% 38%, rgba(190,18,30,0.95) 0%, '
              + 'rgba(130,6,16,0.9) 38%, rgba(70,2,8,0.82) 100%)',
            clipPath: clipFor(sp.shape),
            boxShadow: '0 0 6px rgba(120,0,8,0.5)',
            animation: 'bloodRockSheen ' + sp.dur + 's ease-in-out ' + sp.delay + 's infinite',
          }} />
          {sp.drops.map((d, j) => (
            <div key={'drp' + j} style={{
              position: 'absolute',
              left: '50%', top: '50%',
              width: d.sz + 'px', height: (d.sz * 1.25) + 'px',
              transform: 'translate('
                + (Math.cos(d.a) * sp.s * d.d) + 'px, '
                + (Math.sin(d.a) * sp.s * d.d) + 'px) translate(-50%, -50%)',
              background: 'radial-gradient(circle at 38% 30%, #c41020, #6e0410)',
              borderRadius: '50% 50% 50% 50% / 42% 42% 58% 58%',
              boxShadow: '0 0 3px rgba(110,0,8,0.55)',
            }} />
          ))}
        </div>
      ))}
      {/* Layer 5: red ambient vignette — darkens the edges and casts a
          faint blood glow toward the center for mood. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'radial-gradient(ellipse at 50% 55%, rgba(90,0,8,0.12) 0%, '
          + 'rgba(40,0,4,0.0) 45%, rgba(10,0,2,0.45) 100%)',
      }} />
      <style>{`
        @keyframes bloodRockSheen {
          0%, 100% { filter: brightness(0.92) saturate(1.05); }
          50%      { filter: brightness(1.18) saturate(1.25); }
        }
      `}</style>
    </div>
  );
}

// Tarleinn's Floating Island — a wide sky background with a single
// large grass-topped island floating in the middle, cut by a blue
// river that snakes across the grass plateau.
//
// The island silhouette and river path are FIXED (hardcoded points),
// so the artwork never reshuffles — only the cloud layer is animated.
// (Earlier versions seeded a per-play randomised layout, but that
// added complexity for no real benefit; a static, hand-tuned shape
// reads cleaner and lets us focus the eye on the gameplay.)
function FloatingIslandOverlay() {
  // Hardcoded island geometry. Coordinate space is the SVG viewBox
  // 0..100 in both axes; preserveAspectRatio="none" lets it stretch
  // to fill the board-center container.
  const island = {
    cx: 50, cy: 52, rxBase: 34, ryBase: 14,
    // 18 radial samples — top arc tighter (grass plateau), bottom arc
    // jaggier (rocky underside). Picked once and frozen for the
    // life of the game.
    points: [
      { x: 84.0, y: 53.5 }, { x: 80.6, y: 58.4 }, { x: 75.0, y: 63.8 },
      { x: 67.0, y: 67.1 }, { x: 58.5, y: 69.2 }, { x: 50.0, y: 70.0 },
      { x: 41.5, y: 69.5 }, { x: 33.0, y: 67.6 }, { x: 25.0, y: 64.0 },
      { x: 19.4, y: 58.7 }, { x: 16.0, y: 53.6 }, { x: 16.4, y: 49.2 },
      { x: 19.5, y: 45.8 }, { x: 25.5, y: 43.4 }, { x: 34.0, y: 41.9 },
      { x: 50.0, y: 41.0 }, { x: 66.0, y: 41.9 }, { x: 78.0, y: 44.7 },
    ],
  };

  // Fixed river S-curve across the grass surface.
  const river = {
    d: 'M 31 43.0 C 38 41.5, 46 45.5, 50 43.4 C 54 41.3, 62 45.5, 69 43.0',
    width: 2.6,
  };

  // Clouds — 7 of them, evenly distributed across the sky. Each has
  // its own scale / opacity / speed / starting offset, all hardcoded
  // so the layout doesn't reshuffle on re-render. Negative delays
  // stagger them mid-traversal at frame 0.
  const clouds = [
    { y: 10, scale: 1.05, delay:  -6, dur:  90, opacity: 0.78 },
    { y: 18, scale: 0.85, delay: -32, dur: 110, opacity: 0.65 },
    { y: 28, scale: 1.20, delay: -58, dur:  95, opacity: 0.72 },
    { y: 14, scale: 0.70, delay: -82, dur: 120, opacity: 0.55 },
    { y: 24, scale: 0.95, delay: -22, dur: 100, opacity: 0.68 },
    { y: 36, scale: 0.80, delay: -68, dur: 115, opacity: 0.60 },
    { y:  6, scale: 1.10, delay: -45, dur:  85, opacity: 0.74 },
  ];

  // Build the island polygon path — a closed Catmull-Rom-ish smooth via
  // simple Bezier between samples works fine; we use a quadratic-ish
  // smooth by routing through midpoints, which keeps the look soft
  // without introducing self-intersections from sharp jitters.
  const polyPath = useMemo(() => {
    const pts = island.points;
    if (pts.length === 0) return '';
    const mid = (a, b) => ({ x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 });
    let d = '';
    const first = mid(pts[pts.length - 1], pts[0]);
    d += `M ${first.x} ${first.y} `;
    for (let i = 0; i < pts.length; i++) {
      const cur = pts[i];
      const nxt = pts[(i + 1) % pts.length];
      const m = mid(cur, nxt);
      d += `Q ${cur.x} ${cur.y}, ${m.x} ${m.y} `;
    }
    d += 'Z';
    return d;
  }, [island]);

  return (
    <div className="floating-island-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
    }}>
      {/* Layer 1: sky gradient (deep blue at top, lighter near horizon). */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'linear-gradient(180deg, rgba(95,165,225,0.55) 0%, rgba(155,205,235,0.45) 55%, rgba(195,225,240,0.40) 100%)',
      }} />
      {/* Layer 2: drifting clouds. Each cloud is a couple of stacked
          ellipses + soft white blur. They animate horizontally on a
          long loop so the sky reads as alive without distracting. */}
      <div style={{ position: 'absolute', inset: 0, mixBlendMode: 'screen' }}>
        {clouds.map((c, i) => (
          <div key={'fic' + i} style={{
            position: 'absolute',
            // `left` is driven entirely by the keyframe animation — it
            // sweeps from -25% (off-screen left) to 125% (off-screen
            // right) of the parent. Each cloud's `delay` is negative
            // so they start mid-traversal at varied points, giving the
            // sky a continuous-flow feel from frame 0.
            top: c.y + '%',
            opacity: c.opacity,
            '--ficScale': c.scale,
            animation: `floatingIslandCloud ${c.dur}s linear ${c.delay}s infinite`,
          }}>
            <div style={{
              position: 'absolute', left: -50, top: -16,
              width: 100, height: 32, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(245,250,255,0.6) 60%, transparent 90%)',
              filter: 'blur(2px)',
            }} />
            <div style={{
              position: 'absolute', left: -25, top: -28,
              width: 60, height: 32, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(245,250,255,0.5) 60%, transparent 90%)',
              filter: 'blur(2px)',
            }} />
            <div style={{
              position: 'absolute', left: 5, top: -22,
              width: 50, height: 26, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(255,255,255,0.95) 0%, rgba(245,250,255,0.55) 60%, transparent 90%)',
              filter: 'blur(2px)',
            }} />
          </div>
        ))}
      </div>
      {/* Layer 3: the island itself, plus the river that runs through
          its grass-top surface. Drawn in one SVG so we can clip the
          river to the island silhouette via a clipPath — no matter how
          the random control points fall, the river never spills off
          the rocky underside. */}
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        style={{
          position: 'absolute', inset: 0,
          width: '100%', height: '100%',
          filter: 'drop-shadow(0 6px 14px rgba(20,40,80,0.35))',
        }}
      >
        <defs>
          {/* Grass-to-rock vertical gradient: lush green up top, brown
              dirt mid, deep stone at the underside. */}
          <linearGradient id="floatingIslandBody" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"  stopColor="#5cb85c" />
            <stop offset="22%" stopColor="#3d9a4a" />
            <stop offset="35%" stopColor="#7c5a36" />
            <stop offset="60%" stopColor="#553a22" />
            <stop offset="100%" stopColor="#2c1f12" />
          </linearGradient>
          {/* River gradient: brighter cyan-blue down the middle, deeper
              at the edges, so it reads as flowing water. */}
          <linearGradient id="floatingIslandRiver" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%"  stopColor="#5fc1ee" />
            <stop offset="50%" stopColor="#2c8dd6" />
            <stop offset="100%" stopColor="#1f6db0" />
          </linearGradient>
          {/* Clip the river to the island so it can't overshoot the
              silhouette regardless of where the random control points
              landed. */}
          <clipPath id="floatingIslandClip">
            <path d={polyPath} />
          </clipPath>
        </defs>
        {/* Island body */}
        <path d={polyPath} fill="url(#floatingIslandBody)" opacity="0.92" />
        {/* Subtle highlight along the grass surface — a thin lighter
            band hugging the top arc of the island. Cheap shading hack:
            a second copy of the path, scaled vertically, with a green
            tint and additive blend. */}
        <path
          d={polyPath}
          fill="rgba(140,210,140,0.45)"
          transform={`translate(0 -${island.ryBase * 0.35}) scale(1 0.32)`}
          style={{ transformOrigin: `${island.cx}% ${island.cy}%` }}
          clipPath="url(#floatingIslandClip)"
          opacity="0.7"
        />
        {/* River — drawn with two stacked strokes for the highlight */}
        <g clipPath="url(#floatingIslandClip)">
          <path d={river.d} stroke="url(#floatingIslandRiver)"
                strokeWidth={river.width} fill="none" strokeLinecap="round" />
          <path d={river.d} stroke="rgba(220,240,255,0.6)"
                strokeWidth={Math.max(0.35, river.width * 0.35)}
                fill="none" strokeLinecap="round"
                style={{ mixBlendMode: 'screen' }} />
        </g>
        {/* A few dangling roots / rocks under the bottom of the island,
            to sell the "floating" silhouette. Hardcoded positions so
            the underside doesn't shift between re-renders. */}
        {[
          { ox: -19.0, len:  6.5, drift:  1.2, w: 0.7 },
          { ox:  -9.5, len:  9.2, drift: -0.8, w: 0.65 },
          { ox:   0.5, len: 11.0, drift:  0.6, w: 0.8 },
          { ox:   9.0, len:  8.0, drift: -1.4, w: 0.6 },
          { ox:  18.0, len:  6.0, drift:  0.9, w: 0.55 },
        ].map((t, i) => (
          <path
            key={'fitend' + i}
            d={`M ${island.cx + t.ox} ${island.cy + island.ryBase * 0.65} q ${t.drift} ${t.len * 0.5}, 0 ${t.len}`}
            stroke="#3a2a18" strokeWidth={t.w}
            fill="none" strokeLinecap="round" opacity="0.85"
          />
        ))}
      </svg>
      <style>{`
        @keyframes floatingIslandCloud {
          0%   { left: -25%; transform: translateY(-50%) scale(var(--ficScale, 1)); }
          100% { left: 125%; transform: translateY(-50%) scale(var(--ficScale, 1)); }
        }
      `}</style>
    </div>
  );
}

// Gathering Storm — dark-red storm clouds drifting across the
// battlefield with red lightning bolts arcing inside and between them.
// Renders while ANY Gathering Storm card is attached in either player's
// support zone (it's an Attachment Spell, not an Area, so we walk
// support zones rather than areaZones).
//
// The overlay is composed of three layers:
//   1. Faint blood-red sky tint over the board so the clouds read as
//      "ominous storm front" rather than just "purple smudges".
//   2. A pool of crimson cloud sprites animating horizontally across
//      the battlefield at varied heights / speeds. Each cloud is a
//      handful of stacked elliptical blurs in deep-red gradients.
//   3. Lightning bursts that fire on randomised intervals — each is an
//      SVG polyline with a couple of branching forks, drawn in bright
//      red with a hot-pink core stroke for the glow.
//
// The lightning timing is driven by a single lightweight effect that
// rotates which "bolt slot" is currently flashing, keeping the React
// state churn cheap regardless of how many bolts the user sees.
function GatheringStormOverlay() {
  // Heavy, fast-moving cloud cover. Bigger sprites, more of them,
  // shorter loop durations — the storm reads as gale-force wind
  // ripping clouds across the battlefield. The slight reverse-flow
  // current (~25% of clouds going against the prevailing wind) adds
  // chaos without breaking the "wind direction" feel.
  const clouds = useMemo(() => Array.from({ length: 22 }, () => ({
    y:        -8 + Math.random() * 116,             // Wider vertical spread
    scale:    1.4 + Math.random() * 1.5,            // Much bigger (was 0.7–1.7)
    delay:    -Math.random() * 14,                  // Spread starts across the cycle
    dur:      8 + Math.random() * 7,                // Way faster (was 24–46s)
    opacity:  0.6 + Math.random() * 0.3,
    // Mostly forward, some against — strong prevailing wind with the
    // occasional updraft cross-current.
    reverse:  Math.random() < 0.25,
  })), []);

  // 6 lightning slots: each slot owns a randomised path; a rotating
  // index makes one slot "hot" at a time, restarting its CSS animation
  // by toggling a `key`. This keeps the lightning visually unpredictable
  // without re-mounting the whole overlay.
  const bolts = useMemo(() => Array.from({ length: 6 }, () => {
    // Bolts typically jag from one cloud strata down to another (not
    // floor-to-ceiling). x1/x2 are within the central battlefield band;
    // y1/y2 keep the bolt within the cloud strata.
    const x1 = 12 + Math.random() * 76;
    const y1 = 8  + Math.random() * 30;
    const x2 = x1 + (-25 + Math.random() * 50);
    const y2 = 35 + Math.random() * 50;
    // 3-segment zig-zag with a random fork off the midpoint.
    const midX = (x1 + x2) / 2 + (-8 + Math.random() * 16);
    const midY = (y1 + y2) / 2 + (-5 + Math.random() * 10);
    const forkX = midX + (-12 + Math.random() * 24);
    const forkY = midY + (4 + Math.random() * 14);
    return {
      main: `M ${x1} ${y1} L ${midX} ${midY} L ${x2} ${y2}`,
      fork: `M ${midX} ${midY} L ${forkX} ${forkY}`,
      // Per-bolt jitter for variety — 0.45–0.85s flash duration.
      dur:  450 + Math.random() * 400,
    };
  }), []);
  const [activeBolt, setActiveBolt] = useState(-1);
  const [boltSerial, setBoltSerial] = useState(0); // re-key trigger
  useEffect(() => {
    let cancelled = false;
    const fire = () => {
      if (cancelled) return;
      const idx = Math.floor(Math.random() * bolts.length);
      setActiveBolt(idx);
      setBoltSerial(s => s + 1);
      // Per-strike audio cue — distant thunder. Volume kept very low
      // so a long Gathering Storm session doesn't overwhelm the rest
      // of the soundscape.
      if (window.playSFX) {
        window.playSFX('elem_lightning', { volume: 0.12, dedupe: 250, category: 'effect' });
      }
      // The selected bolt visually disappears after its CSS animation;
      // schedule the NEXT bolt 400–1100ms later to keep the strikes
      // feeling stochastic.
      const gap = 380 + Math.random() * 750;
      setTimeout(fire, gap);
    };
    const initial = setTimeout(fire, 250 + Math.random() * 600);
    return () => { cancelled = true; clearTimeout(initial); };
  }, [bolts.length]);

  return (
    <div className="gathering-storm-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
    }}>
      {/* Layer 1: blood-red atmospheric tint. Soft radial so the
          centre of the battlefield feels "thicker" with storm. */}
      <div style={{
        position: 'absolute', inset: 0,
        background:
          'radial-gradient(ellipse at 50% 50%, rgba(80,8,12,0.32) 0%, rgba(50,4,8,0.22) 55%, rgba(20,2,4,0.18) 100%)',
        mixBlendMode: 'multiply',
      }} />
      {/* Layer 2: drifting crimson cloud sprites. The keyframe drives
          `left` from off-screen left (-25%) to off-screen right (125%)
          so each cloud actually traverses the entire battlefield —
          the previous percentage-based `transform: translate(...)`
          implementation only swept the cloud's own width and parked
          everything near the left edge. */}
      <div style={{ position: 'absolute', inset: 0 }}>
        {clouds.map((c, i) => (
          <div key={'gsc' + i} style={{
            position: 'absolute',
            top: c.y + '%',
            opacity: c.opacity,
            '--gscScale': c.scale,
            animation: `gatheringStormCloud${c.reverse ? 'Rev' : ''} ${c.dur}s linear ${c.delay}s infinite`,
            filter: 'drop-shadow(0 4px 18px rgba(120,12,16,0.5))',
          }}>
            {/* Stacked ellipses make a single cloud sprite. */}
            <div style={{
              position: 'absolute', left: -65, top: -18,
              width: 130, height: 36, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(105,12,18,0.92) 0%, rgba(75,8,14,0.7) 55%, rgba(30,2,6,0) 95%)',
              filter: 'blur(3px)',
            }} />
            <div style={{
              position: 'absolute', left: -32, top: -32,
              width: 78, height: 36, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(125,18,24,0.88) 0%, rgba(85,10,16,0.6) 60%, rgba(30,2,6,0) 95%)',
              filter: 'blur(3px)',
            }} />
            <div style={{
              position: 'absolute', left: 5, top: -26,
              width: 65, height: 30, borderRadius: '50%',
              background: 'radial-gradient(circle, rgba(95,10,16,0.85) 0%, rgba(60,6,12,0.55) 60%, rgba(20,1,4,0) 95%)',
              filter: 'blur(3px)',
            }} />
            {/* A crimson "underbelly" smear hints at active rain inside
                the cloud. */}
            <div style={{
              position: 'absolute', left: -45, top: 4,
              width: 95, height: 14, borderRadius: '50%',
              background: 'radial-gradient(ellipse, rgba(60,4,8,0.7) 0%, rgba(30,2,4,0) 80%)',
              filter: 'blur(4px)',
            }} />
          </div>
        ))}
      </div>
      {/* Layer 3: lightning bolts. We render an SVG with all bolts laid
          out, but only the `activeBolt` is visible at any moment via
          opacity. Re-keying the visible <g> on `boltSerial` restarts
          the strike-flash animation. */}
      <svg
        viewBox="0 0 100 100"
        preserveAspectRatio="none"
        style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}
      >
        <defs>
          <filter id="gatheringStormGlow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="1.2" />
          </filter>
        </defs>
        {bolts.map((b, i) => activeBolt === i ? (
          <g
            key={'gsb' + i + '-' + boltSerial}
            style={{
              animation: `gatheringStormBolt ${b.dur}ms ease-out forwards`,
            }}
          >
            {/* Outer red glow */}
            <path d={b.main} stroke="#ff1830" strokeWidth="1.4"
                  fill="none" strokeLinecap="round"
                  filter="url(#gatheringStormGlow)" opacity="0.9" />
            <path d={b.fork} stroke="#ff1830" strokeWidth="1.0"
                  fill="none" strokeLinecap="round"
                  filter="url(#gatheringStormGlow)" opacity="0.85" />
            {/* Inner bright core */}
            <path d={b.main} stroke="#ffd0d8" strokeWidth="0.55"
                  fill="none" strokeLinecap="round" />
            <path d={b.fork} stroke="#ffd0d8" strokeWidth="0.4"
                  fill="none" strokeLinecap="round" />
          </g>
        ) : null)}
      </svg>
      <style>{`
        @keyframes gatheringStormCloud {
          0%   { left: -25%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
          100% { left: 125%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
        }
        @keyframes gatheringStormCloudRev {
          0%   { left: 125%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
          100% { left: -25%;  transform: translateY(-50%) scale(var(--gscScale, 1)); }
        }
        @keyframes gatheringStormBolt {
          0%   { opacity: 0; }
          12%  { opacity: 1; }
          25%  { opacity: 0.7; }
          40%  { opacity: 1; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

// Wowhalla gears — battlefield-wide ambient background painted while
// "Wowhalla, the Hall of the Cool" is in either player's Area zone.
// Large brass-colored gears slowly rotate behind the cards and zones
// (z-index 1 — above the board skin, beneath every card / hero / zone
// frame). Counter-rotating directions and varied sizes keep the
// composition lively without distracting from gameplay.
function WowhallaGearsOverlay() {
  const gears = useMemo(() => {
    // Hand-tuned + filler positions so gears densely populate the
    // battlefield without all clumping. `cw` is now derived at mount
    // (see effect below) by 2-colouring the touch-graph so that any
    // two gears whose outer circles overlap spin in opposite
    // directions, like meshing teeth on real machinery.
    return [
      // Anchors
      { left: -6,   top: 6,    size: 260, dur: 46, delay: 0 },
      { left: 78,   top: -8,   size: 320, dur: 58, delay: -10 },
      { left: 92,   top: 58,   size: 220, dur: 32, delay: -3 },
      { left: 14,   top: 76,   size: 280, dur: 48, delay: -18 },
      { left: 40,   top: 22,   size: 180, dur: 28, delay: -7 },
      { left: 55,   top: 84,   size: 200, dur: 36, delay: -22 },
      { left: -10,  top: 44,   size: 170, dur: 30, delay: -2 },
      // Mid-band fillers
      { left: 22,   top: 38,   size: 130, dur: 24, delay: -12 },
      { left: 62,   top: 30,   size: 150, dur: 26, delay: -16 },
      { left: 36,   top: 56,   size: 140, dur: 22, delay: -4 },
      { left: 72,   top: 50,   size: 130, dur: 20, delay: -9 },
      { left: 8,    top: 26,   size: 110, dur: 18, delay: -1 },
      { left: 50,   top: 12,   size: 120, dur: 22, delay: -14 },
      { left: 84,   top: 36,   size: 140, dur: 24, delay: -8 },
      { left: 4,    top: 60,   size: 130, dur: 26, delay: -19 },
      { left: 32,   top: 8,    size: 100, dur: 16, delay: -5 },
      { left: 66,   top: 70,   size: 160, dur: 30, delay: -11 },
      { left: 46,   top: 70,   size: 110, dur: 18, delay: -15 },
      { left: 26,   top: 92,   size: 150, dur: 28, delay: -23 },
      { left: 76,   top: 92,   size: 130, dur: 22, delay: -6 },
      { left: 96,   top: 80,   size: 110, dur: 20, delay: -13 },
      { left: -2,   top: 88,   size: 120, dur: 22, delay: -20 },
    ];
  }, []);

  // Touch-graph 2-colouring — touching gears must spin oppositely.
  // The container's pixel size is needed to convert `left/top` (%) to
  // actual centres, so we compute the colouring after layout and
  // re-run on resize. Falls back to all-clockwise pre-measurement.
  const containerRef = useRef(null);
  const [spinDirs, setSpinDirs] = useState(() => gears.map(() => true));
  useLayoutEffect(() => {
    const recompute = () => {
      const el = containerRef.current;
      if (!el) return;
      const w = el.offsetWidth || el.clientWidth;
      const h = el.offsetHeight || el.clientHeight;
      if (!w || !h) return;
      // Project each gear's centre into pixel space. `marginLeft/Top`
      // is `-size/2`, so the rendered centre is at exactly
      // `(left% * w, top% * h)`.
      const cx = gears.map(g => (g.left / 100) * w);
      const cy = gears.map(g => (g.top  / 100) * h);
      const r  = gears.map(g => g.size / 2);
      // Build adjacency: any two gears whose outer circles overlap
      // (centre distance < sum of radii) are "touching" and need
      // opposite directions.
      const adj = gears.map(() => []);
      for (let i = 0; i < gears.length; i++) {
        for (let j = i + 1; j < gears.length; j++) {
          const dx = cx[i] - cx[j];
          const dy = cy[i] - cy[j];
          if (Math.hypot(dx, dy) < r[i] + r[j]) {
            adj[i].push(j); adj[j].push(i);
          }
        }
      }
      // BFS 2-colouring per connected component. If the graph isn't
      // bipartite (an odd cycle of touching gears) at least one
      // adjacent pair will end up same-coloured — that's mechanically
      // unavoidable, so accept it rather than thrashing.
      const colour = new Array(gears.length).fill(null);
      for (let s = 0; s < gears.length; s++) {
        if (colour[s] !== null) continue;
        colour[s] = true;
        const queue = [s];
        while (queue.length) {
          const u = queue.shift();
          for (const v of adj[u]) {
            if (colour[v] === null) {
              colour[v] = !colour[u];
              queue.push(v);
            }
          }
        }
      }
      setSpinDirs(colour.map(c => c !== null ? c : true));
    };
    recompute();
    let ro;
    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
      ro = new ResizeObserver(recompute);
      ro.observe(containerRef.current);
    } else {
      window.addEventListener('resize', recompute);
    }
    return () => {
      if (ro) ro.disconnect();
      else window.removeEventListener('resize', recompute);
    };
  }, [gears]);
  // SVG gear, drawn once and re-used per instance via a CSS rotation.
  // Brass palette: outer #b78b3a, inner #d6a64a, highlight #f1cc6e.
  const gearSvg = `
    <svg xmlns='http://www.w3.org/2000/svg' viewBox='-100 -100 200 200'>
      <defs>
        <radialGradient id='gg' cx='0' cy='0' r='100' gradientUnits='userSpaceOnUse'>
          <stop offset='0%' stop-color='#f1cc6e'/>
          <stop offset='55%' stop-color='#c89844'/>
          <stop offset='100%' stop-color='#7a5a23'/>
        </radialGradient>
        <radialGradient id='gh' cx='0' cy='0' r='30' gradientUnits='userSpaceOnUse'>
          <stop offset='0%' stop-color='#3a2a10'/>
          <stop offset='100%' stop-color='#0f0a04'/>
        </radialGradient>
      </defs>
      <g>
        ${Array.from({ length: 12 }).map((_, i) => {
          const a = (i * 360 / 12);
          return `<rect x='-9' y='-95' width='18' height='22' rx='3' fill='url(#gg)' transform='rotate(${a})'/>`;
        }).join('')}
        <circle cx='0' cy='0' r='78' fill='url(#gg)' stroke='#5b4118' stroke-width='4'/>
        <circle cx='0' cy='0' r='52' fill='none' stroke='#5b4118' stroke-width='3'/>
        ${Array.from({ length: 8 }).map((_, i) => {
          const a = (i * 360 / 8) * Math.PI / 180;
          const x = Math.cos(a) * 65, y = Math.sin(a) * 65;
          return `<circle cx='${x.toFixed(1)}' cy='${y.toFixed(1)}' r='7' fill='#5b4118'/>`;
        }).join('')}
        <circle cx='0' cy='0' r='22' fill='url(#gh)' stroke='#3a2a10' stroke-width='3'/>
      </g>
    </svg>
  `;
  const dataUrl = 'data:image/svg+xml;utf8,' + encodeURIComponent(gearSvg);
  return (
    <div ref={containerRef} className="wowhalla-gears-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      // No explicit z-index — DOM order keeps the gears beneath every
      // sibling card / hero / zone frame painted after this overlay.
      // Setting z-index would otherwise promote the gears above any
      // sibling that doesn't declare a higher z-index of its own.
      overflow: 'hidden',
      // Slight warm tint — barely visible but ties the gears to a brass-lit hall.
      background: 'radial-gradient(ellipse at 50% 50%, rgba(140,90,40,0.06) 0%, transparent 70%)',
    }}>
      {gears.map((g, i) => (
        <div key={'wg' + i} style={{
          position: 'absolute',
          left: g.left + '%', top: g.top + '%',
          width: g.size + 'px', height: g.size + 'px',
          marginLeft: -g.size / 2, marginTop: -g.size / 2,
          backgroundImage: `url("${dataUrl}")`,
          backgroundSize: 'contain', backgroundRepeat: 'no-repeat',
          backgroundPosition: 'center',
          opacity: 0.42,
          filter: 'drop-shadow(0 4px 8px rgba(0,0,0,.55))',
          animation: 'wowhallaGearSpin ' + g.dur + 's linear ' + g.delay + 's infinite ' + (spinDirs[i] ? 'normal' : 'reverse'),
        }} />
      ))}
      <style>{`
        @keyframes wowhallaGearSpin {
          0%   { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

// Tempeste rain — permanent rain background painted while at least one
// Prophecy of Tempeste is attached. Stormy slate-blue drops with a brief
// lightning flicker every few seconds. Lighter on the atmospheric tint
// than Acid Rain since Tempeste isn't supposed to be a hostile area
// effect — it's the host's chosen burden, ambient and ominous.
function TempesteRainOverlay() {
  const drops = useMemo(() => Array.from({ length: 130 }, () => ({
    left: Math.random() * 100,
    delay: -Math.random() * 1.4,
    dur: 0.45 + Math.random() * 0.55,
    w: 1 + Math.random() * 1.4,
    h: 16 + Math.random() * 26,
    opacity: 0.4 + Math.random() * 0.5,
  })), []);
  const splashes = useMemo(() => Array.from({ length: 18 }, () => ({
    left: Math.random() * 100,
    top: 60 + Math.random() * 36,
    delay: -Math.random() * 1.4,
    dur: 0.5 + Math.random() * 0.4,
    size: 5 + Math.random() * 9,
  })), []);
  // Sporadic lightning flickers behind the rain — re-keyed via interval.
  const [flickerSerial, setFlickerSerial] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const fire = () => {
      if (cancelled) return;
      setFlickerSerial(s => s + 1);
      setTimeout(fire, 3500 + Math.random() * 4500);
    };
    const initial = setTimeout(fire, 1200 + Math.random() * 2000);
    return () => { cancelled = true; clearTimeout(initial); };
  }, []);
  return (
    <div className="tempeste-rain-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 178,
      overflow: 'hidden',
      background: 'linear-gradient(180deg, rgba(20,30,55,0.18) 0%, rgba(10,20,40,0.30) 100%)',
    }}>
      {/* Background lightning flicker — full-overlay desaturated flash. */}
      <div key={'tflk' + flickerSerial} style={{
        position: 'absolute', inset: 0,
        background: 'radial-gradient(ellipse at 50% 30%, rgba(220,230,255,0.45) 0%, rgba(160,180,220,0.18) 35%, transparent 70%)',
        opacity: 0,
        animation: 'tempesteFlicker 700ms ease-out forwards',
      }} />
      {drops.map((d, i) => (
        <span key={'td'+i} style={{
          position: 'absolute',
          left: d.left + '%', top: '-10%',
          width: d.w + 'px', height: d.h + 'px',
          background: 'linear-gradient(180deg, rgba(80,110,160,0) 0%, rgba(120,150,200,' + d.opacity + ') 30%, rgba(170,200,235,' + d.opacity + ') 70%, rgba(220,235,255,' + d.opacity + ') 100%)',
          boxShadow: '0 0 3px rgba(150,180,220,' + (d.opacity * 0.5) + ')',
          borderRadius: d.w + 'px',
          animation: 'tempesteRainDrop ' + d.dur + 's linear ' + d.delay + 's infinite',
        }} />
      ))}
      {splashes.map((s, i) => (
        <span key={'ts'+i} style={{
          position: 'absolute',
          left: s.left + '%', top: s.top + '%',
          width: s.size + 'px', height: (s.size * 0.45) + 'px',
          border: '1.5px solid rgba(190,215,245,0.7)',
          borderTop: 'transparent',
          borderRadius: '50%',
          animation: 'tempesteRainSplash ' + s.dur + 's ease-out ' + s.delay + 's infinite',
          opacity: 0,
        }} />
      ))}
      <style>{`
        @keyframes tempesteRainDrop {
          0%   { transform: translateY(0) translateX(0); }
          100% { transform: translateY(115vh) translateX(-6px); }
        }
        @keyframes tempesteRainSplash {
          0%   { opacity: 0; transform: scale(0.3); }
          35%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.6); }
        }
        @keyframes tempesteFlicker {
          0%   { opacity: 0; }
          15%  { opacity: 0.85; }
          30%  { opacity: 0.4;  }
          45%  { opacity: 0.95; }
          100% { opacity: 0; }
        }
      `}</style>
    </div>
  );
}

function AcidRainOverlay() {
  // Spawn a large pool of drops with staggered delays / durations so the
  // rain reads as "continuous" without any visible reset point.
  const drops = useMemo(() => Array.from({ length: 110 }, () => ({
    left: Math.random() * 100,
    delay: -Math.random() * 1.6,
    dur: 0.55 + Math.random() * 0.55,
    w: 1 + Math.random() * 1.8,
    h: 14 + Math.random() * 28,
    opacity: 0.45 + Math.random() * 0.45,
  })), []);
  const splashes = useMemo(() => Array.from({ length: 14 }, () => ({
    left: Math.random() * 100,
    top: 55 + Math.random() * 40,
    delay: -Math.random() * 1.5,
    dur: 0.5 + Math.random() * 0.4,
    size: 6 + Math.random() * 10,
  })), []);
  return (
    <div className="acid-rain-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 180,
      overflow: 'hidden',
      background: 'radial-gradient(ellipse at center, rgba(80,0,10,0.15) 0%, rgba(20,0,5,0.28) 100%)',
      mixBlendMode: 'normal',
    }}>
      {drops.map((d, i) => (
        <span key={'d'+i} style={{
          position: 'absolute',
          left: d.left + '%', top: '-10%',
          width: d.w + 'px', height: d.h + 'px',
          background: 'linear-gradient(180deg, rgba(180,15,25,0) 0%, rgba(200,30,40,' + d.opacity + ') 30%, rgba(255,60,80,' + d.opacity + ') 70%, rgba(255,120,140,' + d.opacity + ') 100%)',
          boxShadow: '0 0 3px rgba(220,40,50,' + (d.opacity * 0.6) + ')',
          borderRadius: d.w + 'px',
          animation: 'acidRainDrop ' + d.dur + 's linear ' + d.delay + 's infinite',
        }} />
      ))}
      {splashes.map((s, i) => (
        <span key={'s'+i} style={{
          position: 'absolute',
          left: s.left + '%', top: s.top + '%',
          width: s.size + 'px', height: (s.size * 0.45) + 'px',
          border: '1.5px solid rgba(255,70,90,0.75)',
          borderTop: 'transparent',
          borderRadius: '50%',
          animation: 'acidRainSplash ' + s.dur + 's ease-out ' + s.delay + 's infinite',
          opacity: 0,
        }} />
      ))}
      <style>{`
        @keyframes acidRainDrop {
          0%   { transform: translateY(0) translateX(0); }
          100% { transform: translateY(115vh) translateX(-8px); }
        }
        @keyframes acidRainSplash {
          0%   { opacity: 0; transform: scale(0.3); }
          35%  { opacity: 1; transform: scale(1); }
          100% { opacity: 0; transform: scale(1.6); }
        }
      `}</style>
    </div>
  );
}

// The Bonegrinder — a thinned litter of bones and skulls covering the
// battlefield while the Spell occupies an Area Zone. Rendered as a
// single large overlay with ~40 randomly-placed bones plus ~14
// skulls. Pinned via `inset: 0` so it covers the whole game-board
// container; pointer-events disabled so it never blocks clicks on
// cards / zones below.
//
// Performance notes:
//   • Counts dialed back from 120/40 → 40/14 after the user reported
//     the dense version still dragged on perf. Slightly larger size
//     range compensates for the lower count visually so the field
//     still reads as a boneyard rather than a sparse scatter.
//   • Static positioning ONLY — no per-element animation. Simultaneous
//     CSS animation timelines added a measurable compositor cost
//     during the initial paint; the random rotations + opacities sell
//     "chaotic bone field" without them.
//   • Wrapped in React.memo so the overlay tree only mounts once.
//     Without this, every gameState sync forced a re-walk of all the
//     children even though their props never change.
//   • Random scatter is pre-computed via `useMemo([])` so the same
//     positions persist across the component's lifetime — picking
//     up Bonegrinder mid-game and replaying doesn't reshuffle.
const BonegrinderOverlay = React.memo(function BonegrinderOverlay() {
  // Bone scatter — fully random rotations + wide size range so the
  // pile reads as chaotic. Position is independent x/y random so
  // bones land in zone gaps as well as empty corners.
  const bones = useMemo(() => Array.from({ length: 40 }, () => ({
    left: Math.random() * 100,
    top:  Math.random() * 100,
    size: 22 + Math.random() * 32,
    rot:  (Math.random() * 360) | 0,
    opacity: 0.55 + Math.random() * 0.4,
  })), []);
  // Skulls are slightly bigger on average — rarer and more
  // attention-grabbing — and stay close to upright (±25°).
  const skulls = useMemo(() => Array.from({ length: 14 }, () => ({
    left: Math.random() * 100,
    top:  Math.random() * 100,
    size: 26 + Math.random() * 24,
    rot:  (Math.random() * 50 - 25) | 0,
    opacity: 0.7 + Math.random() * 0.3,
  })), []);
  return (
    <div className="bonegrinder-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      // zIndex -1 paints this layer BENEATH the board's in-flow
      // content (player sides, area / support / hero / ability /
      // surprise zones, cards). The parent `.board-center` sets
      // `isolation: isolate` so this negative z-index stays confined
      // to the board container — bones don't leak behind the page
      // background. Net result: the litter coats the battlefield
      // floor under everything, never on top of cards or buttons.
      zIndex: -1,
      overflow: 'hidden',
      // Faint warm-bone wash behind the litter — sells "boneyard"
      // without darkening the underlying board.
      background: 'radial-gradient(ellipse at center, rgba(60,40,20,0.10) 0%, rgba(30,20,10,0.18) 100%)',
    }}>
      {bones.map((b, i) => (
        <span key={'b'+i} style={{
          position: 'absolute',
          left: b.left + '%', top: b.top + '%',
          fontSize: b.size + 'px',
          opacity: b.opacity,
          transform: `translate(-50%, -50%) rotate(${b.rot}deg)`,
          textShadow: '0 1px 2px rgba(0,0,0,0.7)',
        }}>🦴</span>
      ))}
      {skulls.map((s, i) => (
        <span key={'s'+i} style={{
          position: 'absolute',
          left: s.left + '%', top: s.top + '%',
          fontSize: s.size + 'px',
          opacity: s.opacity,
          transform: `translate(-50%, -50%) rotate(${s.rot}deg)`,
          textShadow: '0 1px 3px rgba(0,0,0,0.8)',
        }}>💀</span>
      ))}
    </div>
  );
});

// Crystal Well — gemstones of all kinds scattered across the
// battlefield floor while the Spell occupies an Area Zone. Same
// pattern as the Bonegrinder overlay: pre-computed random scatter
// (no per-paint recompute), `inset: 0` to coat the whole board,
// `pointerEvents: none` so it never blocks card / zone interaction.
// zIndex -1 paints under the in-flow board contents.
//
// Variety comes from a fixed palette of `filter: hue-rotate(...)
// saturate(...)` recipes applied to the same 💎 glyph — sapphire
// (default blue), ruby, emerald, topaz/amber, amethyst, citrine.
// Each recipe is hand-tuned to a vivid full-saturation tone so the
// floor reads as a treasure of multi-coloured crystals instead of
// a wash of muted hues. NOT randomized — the engine picks one of
// the discrete recipes per gem.
const CrystalWellOverlay = React.memo(function CrystalWellOverlay() {
  // Each entry pairs a CSS filter that re-tints the default-blue
  // 💎 glyph with a matching glow color so the text-shadow halos
  // each gem in its own light. Saturation/brightness intentionally
  // boosted so the colors stay vivid against the dark board.
  const GEM_VARIANTS = [
    // Sapphire — the default blue, just amped.
    { filter: 'saturate(1.6) brightness(1.15)',                      glow: '255, 60, 60'  /* unused */, label: 'sapphire' },
    // Ruby — strong red.
    { filter: 'hue-rotate(180deg) saturate(2.4) brightness(1.1)',    glow: '255, 60, 60',                  label: 'ruby' },
    // Emerald — vivid green.
    { filter: 'hue-rotate(120deg) saturate(2.2) brightness(1.05)',   glow: '60, 255, 120',                 label: 'emerald' },
    // Topaz / amber — bright orange.
    { filter: 'hue-rotate(150deg) saturate(2.5) brightness(1.2)',    glow: '255, 160, 40',                 label: 'topaz' },
    // Amethyst — saturated purple.
    { filter: 'hue-rotate(-90deg) saturate(2.0) brightness(1.05)',   glow: '210, 90, 255',                 label: 'amethyst' },
    // Citrine — bright yellow.
    { filter: 'hue-rotate(165deg) saturate(2.6) brightness(1.3)',    glow: '255, 230, 60',                 label: 'citrine' },
  ];
  // Override the sapphire glow now that the array is defined (the
  // first entry's `glow` was a placeholder). Done here rather than
  // inline to keep the table easy to read.
  GEM_VARIANTS[0].glow = '90, 170, 255';

  const gems = useMemo(() => Array.from({ length: 48 }, () => ({
    variant: GEM_VARIANTS[(Math.random() * GEM_VARIANTS.length) | 0],
    left: Math.random() * 100,
    top:  Math.random() * 100,
    // Wider scaling range than the Bonegrinder bones — small chips
    // alongside fist-sized centerpieces sells "treasure".
    size: 18 + Math.random() * 42,
    rot:  (Math.random() * 360) | 0,
    opacity: 0.7 + Math.random() * 0.3,
  })), []);

  return (
    <div className="crystal-well-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      zIndex: -1,
      overflow: 'hidden',
      // Faint cool wash behind the gem litter so the colored gems
      // pop without the board background fighting them.
      background: 'radial-gradient(ellipse at center, rgba(40,80,120,0.10) 0%, rgba(20,40,80,0.18) 100%)',
    }}>
      {gems.map((g, i) => (
        <span key={'g'+i} style={{
          position: 'absolute',
          left: g.left + '%', top: g.top + '%',
          fontSize: g.size + 'px',
          opacity: g.opacity,
          transform: `translate(-50%, -50%) rotate(${g.rot}deg)`,
          filter: `${g.variant.filter} drop-shadow(0 0 6px rgba(${g.variant.glow}, 0.55))`,
        }}>💎</span>
      ))}
    </div>
  );
});

// Stinky Stables — enormous face-less dung piles pinned to the LEFT/RIGHT
// margins of the battlefield (zones live in the central ~80%). Unicode has
// no face-less poop emoji (💩 always has eyes/mouth), so each pile is drawn
// as stacked SVG swirls with brown radial gradients. Rendered as the first
// sibling inside .board-center with NO explicit z-index — later flex
// siblings (player sides, area zones, cards) therefore paint on top at
// equal-auto stacking. Stink lines drift up from each pile, flies orbit
// them in little elliptical loops, and a few free-fliers cross the air.
function StinkyStablesOverlay() {
  // 4 piles per side, vertically spread. Horizontal jitter stays inside
  // the safe outer-margin strip (≈3–7% on each side) so piles never drift
  // into the zone-filled middle.
  const piles = useMemo(() => {
    const makeSide = (xBase, flip) => Array.from({ length: 4 }, (_, i) => ({
      left: xBase + (Math.random() * 3 - 1.5),
      top: 6 + i * 23 + (Math.random() * 6 - 3),
      size: 80 + Math.random() * 55,
      skew: -8 + Math.random() * 16,
      flipX: flip,
      tint: Math.floor(Math.random() * 3),
    }));
    return [...makeSide(4, 1), ...makeSide(96, -1)];
  }, []);
  // Flies orbiting each pile — per-fly elliptical radii + phase so the
  // swarm doesn't read as marching in lockstep.
  const orbitFlies = useMemo(() => piles.flatMap((p, pi) =>
    Array.from({ length: 3 + Math.floor(Math.random() * 2) }, () => ({
      pileIdx: pi,
      anchorLeft: p.left,
      anchorTop: p.top,
      rx: 18 + Math.random() * 20,
      ry: 10 + Math.random() * 14,
      phase: Math.random(),
      dur: 2.6 + Math.random() * 2.2,
      size: 2.3 + Math.random() * 1.8,
    }))
  ), [piles]);
  // A handful of free flies meander across the battlefield air.
  const freeFlies = useMemo(() => Array.from({ length: 8 }, () => ({
    left: 3 + Math.random() * 94,
    top: 8 + Math.random() * 80,
    delay: -Math.random() * 3.5,
    dur: 3.5 + Math.random() * 2.5,
    size: 2 + Math.random() * 1.4,
  })), []);
  // Two or three wavy smoke trails rising above each pile.
  const stinkLines = useMemo(() => piles.flatMap((p) =>
    Array.from({ length: 2 + Math.floor(Math.random() * 2) }, () => ({
      left: p.left + (Math.random() * 5 - 2.5),
      top: p.top - 3 + (Math.random() * 3 - 1.5),
      delay: -Math.random() * 3,
      dur: 2.8 + Math.random() * 1.6,
      sway: -6 + Math.random() * 12,
    }))
  ), [piles]);
  const tints = [
    { light: '#8a5a2a', mid: '#5a3616', dark: '#321e0a' },
    { light: '#7a4a20', mid: '#4a2a10', dark: '#2a1808' },
    { light: '#94643a', mid: '#624020', dark: '#3a220e' },
  ];
  // Per-fly orbital keyframes — each fly needs its own ellipse. Build the
  // <style> body once via useMemo so it doesn't churn every render.
  const orbitKeyframes = useMemo(() => orbitFlies.map((f, i) =>
    `@keyframes stinkyOrbit${i} {
       0%   { transform: translate(${f.rx.toFixed(1)}px, 0); }
       25%  { transform: translate(0, ${(-f.ry).toFixed(1)}px); }
       50%  { transform: translate(${(-f.rx).toFixed(1)}px, 0); }
       75%  { transform: translate(0, ${f.ry.toFixed(1)}px); }
       100% { transform: translate(${f.rx.toFixed(1)}px, 0); }
     }`
  ).join('\n'), [orbitFlies]);
  return (
    <div className="stinky-stables-overlay" style={{
      position: 'absolute', inset: 0, pointerEvents: 'none',
      overflow: 'hidden',
      // Mild miasma — kept light so it doesn't fight card readability.
      background: 'radial-gradient(ellipse at center, rgba(70,58,24,0.10) 0%, rgba(40,35,15,0.20) 100%)',
    }}>
      {piles.map((p, i) => {
        const c = tints[p.tint];
        const gid = `stinkyPoo${i}`;
        return (
          <div key={'p' + i} style={{
            position: 'absolute',
            left: p.left + '%', top: p.top + '%',
            width: p.size + 'px', height: p.size + 'px',
            transform: `translate(-50%, -50%) scaleX(${p.flipX}) skewX(${p.skew}deg)`,
            filter: 'drop-shadow(0 6px 8px rgba(0,0,0,0.55))',
          }}>
            <svg viewBox="0 0 100 100" width="100%" height="100%">
              <defs>
                <radialGradient id={gid} cx="40%" cy="30%" r="80%">
                  <stop offset="0%" stopColor={c.light} />
                  <stop offset="55%" stopColor={c.mid} />
                  <stop offset="100%" stopColor={c.dark} />
                </radialGradient>
              </defs>
              <ellipse cx="50" cy="94" rx="44" ry="5" fill="rgba(0,0,0,0.45)" />
              <path d="M 8,80 Q 8,60 26,56 Q 50,40 74,56 Q 92,60 92,80 Q 92,93 50,93 Q 8,93 8,80 Z"
                    fill={`url(#${gid})`} />
              <path d="M 22,62 Q 22,44 36,40 Q 50,28 64,40 Q 78,44 78,62 Q 78,73 50,73 Q 22,73 22,62 Z"
                    fill={`url(#${gid})`} />
              <path d="M 36,44 Q 36,28 44,26 Q 50,18 56,26 Q 64,28 64,44 Q 64,54 50,54 Q 36,54 36,44 Z"
                    fill={`url(#${gid})`} />
              <ellipse cx="50" cy="17" rx="3" ry="4.5" fill={c.dark} />
              <ellipse cx="32" cy="66" rx="8" ry="3" fill="rgba(210,170,110,0.32)" />
              <ellipse cx="42" cy="46" rx="6" ry="2.5" fill="rgba(210,170,110,0.32)" />
              <ellipse cx="47" cy="28" rx="3" ry="1.5" fill="rgba(210,170,110,0.38)" />
            </svg>
          </div>
        );
      })}
      {/* Stink lines — wavy green-brown smoke rising above each pile */}
      {stinkLines.map((s, i) => (
        <div key={'s' + i} style={{
          position: 'absolute',
          left: s.left + '%', top: s.top + '%',
          width: 24, height: 70,
          transform: 'translate(-50%, -100%)',
          animation: `stinkyStink ${s.dur}s ease-in-out ${s.delay}s infinite`,
          opacity: 0,
          '--stinkSway': s.sway + 'px',
        }}>
          <svg viewBox="0 0 24 70" width="100%" height="100%" preserveAspectRatio="none">
            <path d="M 12,70 C 18,56 4,44 18,30 C 30,16 6,8 14,0"
                  stroke="rgba(120,150,80,0.75)" strokeWidth="2.2" fill="none"
                  strokeLinecap="round" />
            <path d="M 12,70 C 8,58 20,46 10,34 C 0,22 18,14 12,2"
                  stroke="rgba(100,130,60,0.55)" strokeWidth="1.6" fill="none"
                  strokeLinecap="round" />
          </svg>
        </div>
      ))}
      {/* Orbital flies — anchor wrap + inner transform keeps orbit keyframes
          transform-only while the pile position stays in percent units. */}
      {orbitFlies.map((f, i) => (
        <div key={'of' + i} style={{
          position: 'absolute',
          left: f.anchorLeft + '%', top: f.anchorTop + '%',
          width: 0, height: 0,
        }}>
          <span style={{
            position: 'absolute',
            left: -f.size / 2, top: -f.size / 2,
            width: f.size + 'px', height: f.size + 'px',
            background: '#0a0a0a', borderRadius: '50%',
            boxShadow: '0 0 2px rgba(0,0,0,0.9)',
            animation: `stinkyOrbit${i} ${f.dur}s linear infinite`,
            animationDelay: `-${(f.phase * f.dur).toFixed(2)}s`,
            willChange: 'transform',
          }} />
        </div>
      ))}
      {/* Free-flying flies meandering across the battlefield */}
      {freeFlies.map((f, i) => (
        <span key={'ff' + i} style={{
          position: 'absolute',
          left: f.left + '%', top: f.top + '%',
          width: f.size + 'px', height: f.size + 'px',
          background: '#0a0a0a', borderRadius: '50%',
          boxShadow: '0 0 2px rgba(0,0,0,0.9)',
          animation: `stinkyFlyFree ${f.dur}s ease-in-out ${f.delay}s infinite`,
        }} />
      ))}
      <style>{`
        @keyframes stinkyStink {
          0%   { opacity: 0; transform: translate(-50%, -100%) scale(0.5); }
          25%  { opacity: 0.85; }
          70%  { opacity: 0.45; }
          100% { opacity: 0; transform: translate(calc(-50% + var(--stinkSway, 0px)), -160%) scale(1.1); }
        }
        @keyframes stinkyFlyFree {
          0%   { transform: translate(0, 0); }
          15%  { transform: translate(14px, -8px); }
          30%  { transform: translate(-8px, -18px); }
          50%  { transform: translate(22px, -10px); }
          70%  { transform: translate(6px, -22px); }
          85%  { transform: translate(-14px, -12px); }
          100% { transform: translate(0, 0); }
        }
        ${orbitKeyframes}
      `}</style>
    </div>
  );
}

// Burned overlay — persistent small flame particles on the hero
function BurnedOverlay({ ticking }) {
  const flames = useMemo(() => Array.from({ length: 10 }, () => ({
    x: 8 + Math.random() * 84,
    y: 15 + Math.random() * 70,
    size: 8 + Math.random() * 6,
    delay: Math.random() * 2,
    dur: 0.6 + Math.random() * 0.6,
  })), []);
  return (
    <div className={'status-burned-overlay' + (ticking ? ' burn-ticking' : '')}>
      {flames.map((f, i) => (
        <span key={i} className="burned-particle" style={{
          left: f.x + '%', top: f.y + '%', fontSize: f.size,
          animationDelay: f.delay + 's', animationDuration: f.dur + 's',
        }}>🔥</span>
      ))}
    </div>
  );
}

function PoisonedOverlay({ stacks }) {
  const bubbles = useMemo(() => Array.from({ length: 8 }, () => ({
    x: 10 + Math.random() * 80,
    y: 20 + Math.random() * 60,
    size: 6 + Math.random() * 5,
    delay: Math.random() * 2.5,
    dur: 0.8 + Math.random() * 0.8,
  })), []);
  return (
    <div className="status-poisoned-overlay">
      {bubbles.map((b, i) => (
        <span key={i} className="poisoned-particle" style={{
          left: b.x + '%', top: b.y + '%', fontSize: b.size,
          animationDelay: b.delay + 's', animationDuration: b.dur + 's',
        }}>☠️</span>
      ))}
      {stacks >= 1 && <div className="poison-stack-count">{stacks}</div>}
    </div>
  );
}

// Berserked overlay — persistent dark-magic + red-smoke effect that
// lives on a hero card for as long as the `berserked` status sticks.
// Mounted alongside the other persistent overlays (Burned, Poisoned,
// HealReversed). Two particle layers: small dark-purple sparks
// drifting upward (the "dark magic" half) and slow red-orange smoke
// puffs (the "red smoke" half). Both loop indefinitely — the
// status's lifetime is entirely controller-driven (no auto-expiry),
// so the overlay must keep going until the status is cleansed.
function BerserkedOverlay() {
  const sparks = useMemo(() => Array.from({ length: 10 }, () => ({
    x: 8 + Math.random() * 84,
    y: 30 + Math.random() * 60,
    size: 5 + Math.random() * 5,
    delay: Math.random() * 2.5,
    dur: 1.0 + Math.random() * 0.8,
  })), []);
  const smoke = useMemo(() => Array.from({ length: 6 }, () => ({
    x: 15 + Math.random() * 70,
    size: 12 + Math.random() * 8,
    delay: Math.random() * 2.5,
    dur: 1.6 + Math.random() * 1.0,
  })), []);
  return (
    <div className="status-berserked-overlay">
      {smoke.map((s, i) => (
        <span key={'sm'+i} className="berserked-smoke" style={{
          left: s.x + '%', fontSize: s.size,
          animationDelay: s.delay + 's', animationDuration: s.dur + 's',
        }}>💨</span>
      ))}
      {sparks.map((p, i) => (
        <span key={'sp'+i} className="berserked-particle" style={{
          left: p.x + '%', top: p.y + '%', fontSize: p.size,
          animationDelay: p.delay + 's', animationDuration: p.dur + 's',
        }}>✦</span>
      ))}
    </div>
  );
}

function HealReversedOverlay() {
  const particles = useMemo(() => Array.from({ length: 10 }, () => ({
    x: 10 + Math.random() * 80,
    y: 20 + Math.random() * 60,
    size: 5 + Math.random() * 4,
    delay: Math.random() * 3,
    dur: 1.2 + Math.random() * 1.2,
    isSkull: Math.random() < 0.25,
    color: Math.random() < 0.5,
  })), []);
  return (
    <div className="status-heal-reversed-overlay">
      {particles.map((p, i) => (
        <span key={i} className="heal-reversed-particle" style={{
          left: p.x + '%', top: p.y + '%', fontSize: p.size,
          animationDelay: p.delay + 's', animationDuration: p.dur + 's',
          color: p.isSkull ? '#ddd' : p.color ? '#66ff99' : '#cc66ff',
        }}>{p.isSkull ? '💀' : '✦'}</span>
      ))}
    </div>
  );
}

// Light Ball aura — a soft warm-yellow halo wrapping the host Hero
