                opacity: 0,
                transform: `rotate(${s.rot}deg)`,
                animation: `mummyStripWrap ${s.dur}ms ease-in ${s.delay}ms forwards`,
                '--wrap-sx': `${Math.cos(rad) * 35}px`,
                '--wrap-sy': `${Math.sin(rad) * 35}px`,
