        const hue = ['#fff5dc','#e8d8ff','#c8b0ff','#f5e8b8','#d8c0ff','#fff'][Math.floor(Math.random() * 6)];
        sparkle.textContent = particles[Math.floor(Math.random() * particles.length)];
