                      gap: 'calc(1px * var(--board-scale))',
                      boxShadow: '0 0 calc(5px * var(--board-scale)) #ffcb45, inset 0 0 calc(2px * var(--board-scale)) #ffeec2',
                      border: 'calc(1.5px * var(--board-scale)) solid #2a1505',
